window.SUBJECTS = window.SUBJECTS || [];
window.SUBJECTS.push({"id":"pol","n":"Polity","tab":"Polity","w":"The Constitution, rights, Parliament, courts, states and constitutional bodies.","topics":[{"id":"constitution","n":"Making and Features of the Constitution","qs":[{"id":"q0023","q":"Which of the following languages was NOT included in the Eighth Schedule to the Constitution by the 71st Amendment Act of 1992?","o":["Konkani","Nepali","Manipuri","Maithili"],"a":3,"x":"The 71st Amendment (1992) added Konkani, Manipuri and Nepali to the Eighth Schedule. Maithili came later, with Bodo, Dogri and Santhali, by the 92nd Amendment (2003).","e":"The Eighth Schedule now lists 22 languages.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0024","q":"Which of the following is NOT a feature of the Indian Constitution?","o":["Written constitution","Judicial review","Sovereignty of parliament","Single citizenship"],"a":2,"x":"India follows a blend of parliamentary sovereignty and judicial supremacy: Parliament's laws can be struck down by courts, so 'sovereignty of Parliament' (a British feature) is not a feature of the Indian Constitution.","e":"Written constitution, judicial review and single citizenship are Indian features.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0027","q":"After independence, Part C states and Part D territories were constituted as union territories under the ______ Constitutional Amendment Act.","o":["9th","6th","7th","8th"],"a":2,"x":"The 7th Amendment (1956) carried out the States Reorganisation Act: it ended the Part A/B/C/D classes, creating 14 states and 6 union territories.","e":"The same amendment allowed one High Court to serve two or more states.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0030","q":"Which of the following Articles of the Indian Constitution states the duty of the Union to promote and develop the Hindi language?","o":["Article 328","Article 343","Article 351","Article 327"],"a":2,"x":"Article 351 directs the Union to promote the spread of Hindi and develop it as a medium of expression for India's composite culture.","e":"Article 343: Hindi in Devanagari script is the official language of the Union.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0117","q":"Which of the following languages was added to the Eighth Schedule in 2004?","o":["Tamil","Konkani","Maithili","Manipuri"],"a":2,"x":"Maithili, with Bodo, Dogri and Santhali, was added to the Eighth Schedule by the 92nd Amendment Act of 2003, which came into force in January 2004.","e":"Konkani, Manipuri and Nepali had been added earlier, in 1992.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0151","q":"What was the key reason for the Union Government's centralisation of power during the framing of the Indian Constitution?","o":["To prevent regional parties from gaining power","To ensure that state governments were independent","To protect the unity and integrity of the federal nation","To limit the powers of state governments"],"a":2,"x":"The framers gave the Union strong powers mainly to protect India's unity and integrity after Partition and the integration of the princely states.","e":"That is why India is called a 'Union of States' with a strong centre.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0188","q":"The National Festival of India, Republic Day, commemorates the adoption of which document?","o":["The Indian Independence Act","The Quit India Resolution","The Poona Pact","The Constitution of India"],"a":3,"x":"Republic Day (26 January) marks the day the Constitution came into force in 1950. It had been adopted on 26 November 1949.","e":"26 January was chosen because the Congress declared Purna Swaraj on that day in 1930.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0358","q":"Which Article of the Constitution states that the official language of the Union shall be Hindi in the Devanagari script, with the international form of Indian numerals for official purposes?","o":["Article 340(1)","Article 341(1)","Article 343(1)","Article 342(1)"],"a":2,"x":"Article 343(1): the official language of the Union shall be Hindi in the Devanagari script, with the international form of Indian numerals.","e":"14 September (1949) is celebrated as Hindi Diwas.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0382","q":"Where in the Constitution of India are the provisions regarding the Eighth Schedule, which lists various languages for official purposes, found?","o":["Article 344(1) and Article 351","Article 344(2) and Article 350","Article 10 and Article 344","Article 51A and Article 352"],"a":0,"x":"The Eighth Schedule is linked to Article 344(1) (Official Language Commission) and Article 351 (development of Hindi).","e":"22 languages are now listed.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0395","q":"The Indian President impeachment process has been taken from the Constitution of ________.","o":["The US","The UK","Canada","South Africa"],"a":0,"x":"The procedure for impeaching the President (Article 61) is borrowed from the Constitution of the USA.","e":"Also from the USA: Fundamental Rights, judicial review, removal of SC and HC judges.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0396","q":"The official languages of India are included in which Schedule of the Indian Constitution?","o":["10th","4th","9th","8th"],"a":3,"x":"The Eighth Schedule lists India's recognised languages (now 22).","e":"Tenth Schedule: anti-defection. Ninth Schedule: laws protected from judicial review.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0512","q":"Which among the following Constitutional Amendments is popularly known as \"Anti-Defection Law\"?","o":["52nd","40th","61st","69th"],"a":0,"x":"The 52nd Amendment (1985) is the anti-defection law; it added the Tenth Schedule.","e":"The 91st Amendment (2003) removed the 'split' exception and capped ministries at 15% of the House.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0515","q":"In which of the following years was the last meeting of the Constituent Assembly held?","o":["1940","1947","1959","1950"],"a":3,"x":"The Constituent Assembly met for the last time on 24 January 1950, when members signed the Constitution and elected Dr Rajendra Prasad the first President.","e":"It first met on 9 December 1946; the Constitution was adopted on 26 November 1949.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0553","q":"Who was the chairman of the States Committee of the Constituent Assembly?","o":["Jawaharlal Nehru","Rajendra Prasad","B.R. Ambedkar","Gopinath Bardoloi"],"a":0,"x":"Jawaharlal Nehru chaired the States Committee of the Constituent Assembly, which negotiated with princely states; he also chaired the Union Powers and Union Constitution Committees.","e":"Drafting Committee: Dr B. R. Ambedkar. Rules of Procedure and Steering Committees: Dr Rajendra Prasad.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0554","q":"Which among the following Amendment Bills is known as the ‘Women Reservation Bill’ ?","o":["102","108","105","110"],"a":1,"x":"The 108th Constitution Amendment Bill (2008) was the Women's Reservation Bill; it passed the Rajya Sabha in 2010 but lapsed.","e":"In 2023 women's reservation was finally enacted as the 106th Amendment Act (Nari Shakti Vandan Adhiniyam).","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0555","q":"Which among the following Parts of the Indian Constitution is related with the special provisions relating to certain classes?","o":["XIII","XV","XIV","XVI"],"a":3,"x":"Part XVI (Articles 330–342) has special provisions for certain classes: seats for SCs and STs, the Anglo-Indian community, and the SC, ST and OBC Commissions.","e":"Part XV: Elections. Part XIV: Services. Part XIII: Trade and commerce.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0592","q":"The concept of \"Equal Protection Under Law\" in the Indian Constitution is borrowed from the constitution of which of the following countries?","o":["Australia","United Kingdom","Ireland","United States of America"],"a":3,"x":"'Equal protection of the laws' in Article 14 is borrowed from the US Constitution (14th Amendment); 'equality before law' comes from Britain.","e":"Also from the USA: judicial review, Fundamental Rights, the President as Supreme Commander.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0595","q":"Which among the following Constitutional Amendment incorporated Dadra and Nagar Havelli as a Union Territory?","o":["8th","9th","10th","11th"],"a":2,"x":"The 10th Amendment (1961) made Dadra and Nagar Haveli a Union Territory after its freedom from Portugal.","e":"12th Amendment (1962): Goa, Daman and Diu. 14th Amendment (1962): Puducherry.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0633","q":"Which among the following constitutional amendment is the Land Boundary Agreement (LBA) between India and Bangladesh?","o":["98th","99th","101st","100th"],"a":3,"x":"The 100th Constitution Amendment Act (2015) put the India–Bangladesh Land Boundary Agreement into effect, swapping enclaves (chhitmahals).","e":"India transferred 111 enclaves and received 51.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0672","q":"Which among the following words is not there in the Preamble of the Constitution of India?","o":["Fraternity","Justice","Equality","Protection"],"a":3,"x":"The Preamble speaks of Justice, Liberty, Equality and Fraternity. 'Protection' is not in it.","e":"Words added by the 42nd Amendment (1976): Socialist, Secular, Integrity.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0673","q":"Which among the following constitutional amendments added Bodo, Dogri, Maithili and Santhali languages in the Eighth Schedule?","o":["88th","92nd","98th","102nd"],"a":1,"x":"The 92nd Amendment (2003) added Bodo, Dogri, Maithili and Santhali to the Eighth Schedule, taking the total to 22.","e":"The 71st Amendment (1992) had added Konkani, Manipuri and Nepali.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0675","q":"The concept of \"Five Year Planning\" in the Indian Constitution is borrowed from the constitution of which of the following countries?","o":["United States","United Kingdom","USSR","Japan"],"a":2,"x":"The idea of Five-Year Plans is borrowed from the USSR (Soviet Union), along with the Fundamental Duties and the ideals of justice in the Preamble.","e":"The Soviet Union ran its first Five-Year Plan from 1928.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0713","q":"The concept of \"Freedom of trade and commerce\" in the Indian Constitution is borrowed from the constitution of which of the following countries?","o":["Australia","Canada","United States","Japan"],"a":0,"x":"Freedom of trade, commerce and intercourse (Part XIII), the Concurrent List and joint sittings of Parliament are borrowed from Australia.","e":"From Canada: a federation with a strong centre, and residuary powers with the Centre.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0714","q":"Which among the following constitutional amendments incorporated Goa, Daman and Diu in the Indian Union?","o":["5th","18th","22nd","12th"],"a":3,"x":"The 12th Amendment (1962) added Goa, Daman and Diu to India as a Union Territory, after Operation Vijay (1961).","e":"Goa became a state in 1987.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0715","q":"In which year did Lord Mountbatten address the Constituent Assembly for the last time?","o":["1945","1946","1947","1948"],"a":2,"x":"Lord Mountbatten addressed the Constituent Assembly at the midnight session of 14–15 August 1947 as Governor-General; his time ended in June 1948.","e":"Nehru's 'Tryst with Destiny' speech was made at the same session.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0752","q":"As of April 2020, which one of the following is not mentioned in the Preamble to the Constitution of India?","o":["Justice","Peace","Equality","Liberty"],"a":1,"x":"The Preamble secures Justice, Liberty, Equality and Fraternity. 'Peace' is not in it.","e":"The Preamble was amended only once, by the 42nd Amendment (1976).","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q0755","q":"As of April 2020, which one of the following languages is not a part of the Eighth Schedule to the Constitution of India?","o":["Tulu","Sindhi","Sanskrit","Urdu"],"a":0,"x":"Tulu (coastal Karnataka and Kerala) is not in the Eighth Schedule. Sindhi, Sanskrit and Urdu are.","e":"Tulu speakers have long asked for its inclusion.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q1769","q":"Which schedule of the Indian constitution deals with forms of Oaths or Affirmations?","o":["First","Third","Fifth","Sixth"],"a":1,"x":"The Third Schedule contains the forms of oaths and affirmations for ministers, MPs, MLAs, judges and the CAG.","e":"1st: states and UTs; 2nd: salaries; 3rd: oaths; 4th: Rajya Sabha seats.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1773","q":"In which year did the Eighty sixth amendment of the Indian constitution took place?","o":["2002","2000","1998","2005"],"a":0,"x":"The 86th Amendment (2002) added Article 21A (free and compulsory education for ages 6–14), changed Article 45 and added the 11th Fundamental Duty.","e":"Right to Education Act followed in 2009.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q2053","q":"In which year did the third amendement of the Indian constitution take place?","o":["1951","1954","1953","1952"],"a":1,"x":"The Third Amendment (1954) changed Entry 33 of the Concurrent List on trade and commerce in essential goods.","e":"First Amendment: 1951; Seventh: 1956 (States Reorganisation).","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2095","q":"Through which constitutional amendment words Socialist, Secular and Republic were added in the Preamble of the Indian constitution?","o":["First","Eleventh","Forty fourth","Forty second"],"a":3,"x":"The 42nd Amendment (1976) added 'Socialist', 'Secular' and 'Integrity' to the Preamble.","e":"42nd Amendment is called the 'mini-Constitution'.","src":["Junior Clerk 13 Nov 2021 S1"],"k":"'Republic' was already in the original Preamble of 1950; only 'Socialist' and 'Secular' (and 'Integrity') were added by the 42nd Amendment."},{"id":"q2418","q":"Which of the following countries doesn't have a single, written Constitution, but rather a series of documents and decisions that, taken collectively, are referred to as the constitution?","o":["Germany","USA","United kingdom","Canada"],"a":2,"x":"The United Kingdom has no single written constitution; its constitution is made of statutes, conventions and court decisions.","e":"India's is the longest written constitution in the world.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2506","q":"Which of the following parts of the Indian Constitution is related to the amendments to the Constitution?","o":["Part XIX","Part XX","Part XXI","Part XXII"],"a":1,"x":"Part XX (Article 368) deals with amending the Constitution.","e":"Article 368: amendment procedure.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2507","q":"In which year had M. N. Roy suggested for the formation of a Constituent Assembly?","o":["In 1932","In 1933","In 1934","In 1935"],"a":2,"x":"M.N. Roy first proposed a Constituent Assembly for India in 1934; the Congress officially demanded one in 1935.","e":"The Assembly finally met on 9 December 1946.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2621","q":"With respect to the Indian constitution, which of the following pair is/are correct? I. Third Schedule – Forms of Oaths or Affirmations II. Fourth Schedule – Allocation of seats in the Council of States","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Third Schedule has forms of oaths and affirmations; the Fourth Schedule allocates Rajya Sabha seats to states and UTs. Both pairs are correct.","e":"3rd oaths, 4th Rajya Sabha seats.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q1346","q":"Who among the following is recognised as the \"Father of the Constitution of India\"?","o":["Rajendra Prasad","B. R. Ambedkar","Sachchidananda Sinha","Jawaharlal Nehru"],"a":1,"x":"Dr B. R. Ambedkar, chairman of the Drafting Committee, is called the 'Father of the Indian Constitution'.","e":"Sachchidananda Sinha was the Constituent Assembly's first (temporary) chairman.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1350","q":"The concept of 'Judicial Review' in the Indian Constitution has been borrowed from the constitution of which of the following countries?","o":["United Kingdom","Australia","Japan","United States of America"],"a":3,"x":"Judicial review is borrowed from the Constitution of the USA (Marbury v. Madison, 1803).","e":"From the UK: parliamentary government, rule of law, single citizenship.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1360","q":"Which among the following Constitutional Amendments included the Tamil Nadu Reservation Act of 1994 in the 9th Schedule to protect it from judicial review?","o":["89th","65th","76th","72nd"],"a":2,"x":"The 76th Amendment (1994) placed the Tamil Nadu Reservation Act (69% reservation) in the Ninth Schedule to protect it from judicial review.","e":"The Ninth Schedule was created by the 1st Amendment (1951).","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q2733","q":"The Constituent Assembly took almost ____________ to complete its historic task of drafting the Constitution for an Independent India.","o":["3 years","5 years","7 years","9 years"],"a":0,"x":"The Constituent Assembly took about 3 years (2 years, 11 months, 18 days) to draft the Constitution, from 9 December 1946 to 26 November 1949.","e":"","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q1220","q":"Which statement correctly reflects the constitutional mandate for laws enacted under Articles 2 and 3?","o":["Parliament must amend the First and Fourth Schedules through a separate constitutional amendment.","Laws under Article 3 can be introduced only by state legislatures with the President's prior approval.","They must contain the necessary amendments to the First and Fourth Schedules and may include supplemental and incidental provisions.","Such laws need ratification by at least half the states before affecting the Schedules."],"a":2,"x":"Article 4 says laws under Articles 2 and 3 (admitting or forming states) must amend the First and Fourth Schedules as needed and may add supplemental provisions. They are not treated as constitutional amendments under Article 368.","e":"They pass by simple majority in Parliament.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1234","q":"By which constitutional amendment was the Ninth Schedule added to the Indian Constitution?","o":["First Amendment, 1951","Forty-fourth Amendment, 1978","Forty-second Amendment, 1976","Seventh Amendment, 1956"],"a":0,"x":"The First Amendment (1951) added the Ninth Schedule to protect land-reform laws from court challenge on the ground of violating fundamental rights.","e":"After I.R. Coelho (2007), Ninth Schedule laws added after 24 April 1973 can be reviewed.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1456","q":"Which of the following was the first amendment to the Indian Constitution passed in 1951 by the Provisional Parliament?","o":["Right against Exploitation","Right to Freedom of religion","Cultural and Educational Rights","Right to Freedom of Speech and expression"],"a":3,"x":"The First Amendment (1951) added 'reasonable restrictions' to freedom of speech and expression (Article 19(2)), and also created the Ninth Schedule.","e":"It was passed by the Provisional Parliament under Nehru.","src":["TGT 25 Jun 2023 S3"]},{"id":"q1466","q":"Which Article of the Indian Constitution says that the official language of the Union shall be Hindi in the Devanagari script?","o":["Article 343","Article 280","Article 324","Article 226"],"a":0,"x":"Article 343: the official language of the Union shall be Hindi in the Devanagari script.","e":"Article 280: Finance Commission. Article 324: Election Commission. Article 226: High Court writs.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1501","q":"Which of the following concepts was NOT present in the Preamble of the Indian Constitution before 1976?","o":["Sovereign","Socialist","Democratic","Justice"],"a":1,"x":"'Socialist' (with 'Secular' and 'Integrity') was added to the Preamble by the 42nd Amendment in 1976. 'Sovereign', 'Democratic' and 'Justice' were there from the start.","e":"The Preamble is based on Nehru's Objectives Resolution (1946).","src":["TGT 29 Aug 2025"]},{"id":"q1533","q":"How many Schedules did the original Indian Constitution have at its commencement?","o":["8","15","11","5"],"a":0,"x":"The original Constitution (1950) had 8 Schedules (and 395 Articles in 22 Parts); there are now 12.","e":"9th (1951), 10th (1985), 11th (1992), 12th (1992) were added later.","src":["TGT 24 Aug 2025 S3"]},{"id":"q0792","q":"The Preamble declares India to be a Republic, which means that ____________.","o":["the head of the state is the Home Minister","the head of the state is the Chief Justice of India","the head of the state is the Prime Minister","the head of the state is the President"],"a":3,"x":"A Republic means the head of state is elected, not hereditary. In India the President, elected indirectly for five years, is the head of state.","e":"The UK is a democracy but not a republic, because its head of state is a hereditary monarch.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0809","q":"The 101st Constitutional Amendment Act is related to the introduction of:","o":["Panchayati Raj","Right to Education","Fundamental Rights","Goods and Services Tax (GST)"],"a":3,"x":"The 101st Amendment Act (2016) introduced the Goods and Services Tax, adding Articles 246A, 269A and 279A (GST Council).","e":"GST came into force on 1 July 2017.","src":["PGT 22 Sep 2025"]},{"id":"q0829","q":"Which Article of the Indian Constitution states that 'this Constitution may be called the Constitution of India'?","o":["Article 393","Article 441","Article 1","Article 1 B"],"a":0,"x":"Article 393 gives the short title: 'This Constitution may be called the Constitution of India.'","e":"Article 394A: Hindi translation. Article 395: repeal of the Indian Independence Act and GoI Act, 1935.","src":["PGT 26 Sep 2025"]}]},{"id":"rights","n":"Citizenship, Rights, DPSP and Duties","qs":[{"id":"q0034","q":"Which of the following is NOT included in the Right to Equality in the Indian Constitution?","o":["Abolition of untouchability","Equality of opportunity","Absolute equality","Equality before law"],"a":2,"x":"Articles 14–18 give equality before law, no discrimination, equal opportunity in public jobs, abolition of untouchability and abolition of titles. Equality is not absolute: reasonable classification is allowed.","e":"Reservation under Article 16(4) is possible precisely because equality is not absolute.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0101","q":"Which Article of the Indian Constitution guarantees the Right to Equality Before Law and Equal Protection of Laws?","o":["Article 14","Article 16","Article 15","Article 17"],"a":0,"x":"Article 14: the State shall not deny any person equality before the law or equal protection of the laws within India.","e":"Equality before law comes from British law; equal protection of laws comes from the US Constitution.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0114","q":"Which of the following is NOT a mode of acquiring Indian citizenship?","o":["Investment","Registration","Birth","Descent"],"a":0,"x":"The Citizenship Act, 1955 allows citizenship by birth, descent, registration, naturalisation and incorporation of territory. Investment is not a route.","e":"It can be lost by renunciation, termination or deprivation.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0142","q":"Which of the following Articles of the Constitution of India has provisions regarding citizenship?","o":["Articles 5-11","Articles 1-4","Articles 12-17","Articles 18-21"],"a":0,"x":"Citizenship is in Articles 5–11, Part II of the Constitution; Parliament used Article 11 to pass the Citizenship Act, 1955.","e":"Article 5: citizenship at the commencement of the Constitution.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0155","q":"Which Part of the Indian Constitution has provisions on citizenship?","o":["Part III","Part IV","Part II","Part V"],"a":2,"x":"Part II of the Constitution (Articles 5–11) deals with citizenship.","e":"Part III = Fundamental Rights; Part IV = Directive Principles; Part IVA = Fundamental Duties.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0195","q":"Under the Citizenship Act, 1955, which government authority is referred to as 'a Government in India'?","o":["Only a State Government","Central Government or a State Government","Only the Central Government","Local government"],"a":1,"x":"In the Citizenship Act, 1955, 'a Government in India' means the Central Government or a State Government.","e":"Section 2 of the Act holds the definitions.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0222","q":"Which Article of the Indian Constitution abolishes 'Untouchability'?","o":["Article 17","Article 15","Article 14","Article 16"],"a":0,"x":"Article 17 abolishes untouchability and forbids its practice in any form.","e":"14 equality, 15 no discrimination, 16 jobs, 17 untouchability, 18 titles.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0229","q":"Which of the following statements is correct regarding Overseas Citizenship of India (OCI)?","o":["OCI status can be granted to PIOs from countries that permit dual citizenship under their laws.","The Constitution of India allows dual citizenship through OCI status.","Persons of Indian Origin (PIOs) from Pakistan and Bangladesh are eligible for OCI.","The OCI scheme was introduced by the Government of India in 1986."],"a":0,"x":"OCI status can be given to persons of Indian origin whose country allows dual citizenship in some form. It is not full dual citizenship; it started in 2005, not 1986; and people from Pakistan and Bangladesh are excluded.","e":"OCI card holders get a lifelong multiple-entry visa but cannot vote.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0234","q":"Which Section of the Citizenship Act, 1955, defines the term 'illegal migrant'?","o":["Section 2(1)(b)","Section 2(b)(ii)","Section 2(a)","Section 2(1)(d)"],"a":0,"x":"Section 2(1)(b) of the Citizenship Act, 1955 defines an 'illegal migrant': a foreigner who entered without valid documents, or stayed beyond the permitted time.","e":"The Citizenship (Amendment) Act, 2019 added a proviso to this clause for certain minorities from Afghanistan, Bangladesh and Pakistan.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0304","q":"The Right to Education (RTE) Act in India ensures free and compulsory education for children up to which age?","o":["12 years","18 years","14 years","16 years"],"a":2,"x":"The Right to Education Act, 2009 gives free and compulsory education to children aged 6 to 14, under Article 21A (added by the 86th Amendment, 2002).","e":"It reserves 25% of seats in private unaided schools for disadvantaged children.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0318","q":"The Citizenship Act of 1955 provides how many total ways of acquiring citizenship?","o":["5","6","4","3"],"a":0,"x":"The Citizenship Act, 1955 gives five ways to acquire citizenship: birth, descent, registration, naturalisation and incorporation of territory.","e":"It gives three ways to lose it: renunciation, termination and deprivation.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0346","q":"The right to freedom of speech and expression has been set out in which Article of the Indian Constitution?","o":["Article 20","Article 21","Article 22","Article 19"],"a":3,"x":"Article 19(1)(a) guarantees freedom of speech and expression; Article 19 lists six freedoms in all.","e":"Freedom of the press is read into Article 19(1)(a).","src":["ASO 21 Aug 2025 S2"]},{"id":"q0425","q":"As of 1 January 2024, how many Fundamental Duties are included for citizens in the Indian Constitution?","o":["11","9","7","10"],"a":0,"x":"Article 51A lists 11 Fundamental Duties: 10 were added by the 42nd Amendment (1976) and the 11th (education for children aged 6–14) by the 86th Amendment (2002).","e":"Borrowed from the USSR constitution.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0429","q":"Articles 12 to 35, dealing with Fundamental Rights, are contained in which Part of the Indian Constitution?","o":["Part III","Part II","Part IV","Part I"],"a":0,"x":"Fundamental Rights are in Part III (Articles 12–35), called the 'Magna Carta' of India.","e":"Part IV: Directive Principles (36–51). Part IVA: Fundamental Duties (51A).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0469","q":"Which Article contained in Part IV A of the Indian Constitution deals with Fundamental Duties?","o":["Article 51 'A'","Article 71 ‘A’","Article 61","Article 41"],"a":0,"x":"Article 51A in Part IVA lists the Fundamental Duties, added by the 42nd Amendment (1976) on the Swaran Singh Committee's advice.","e":"There are now 11 duties; the 11th (education for children 6–14) came with the 86th Amendment (2002).","src":["ASO 27 Aug 2025 S1"]},{"id":"q0474","q":"Under the leadership of which Indian Prime Minister were the Fundamental Duties added in the Constitution of India?","o":["Lal Bahadur Shastri","Indira Gandhi","Jawaharlal Nehru","Rajiv Gandhi"],"a":1,"x":"The Fundamental Duties were added by the 42nd Amendment (1976), when Indira Gandhi was Prime Minister, during the Emergency.","e":"The idea was borrowed from the Constitution of the USSR.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1569","q":"Which Article of the Indian Constitution relates to equality before law?","o":["Article 30","Article 12","Article 34","Article 14"],"a":3,"x":"Article 14 guarantees equality before law and equal protection of the laws.","e":"It applies to citizens and non-citizens alike.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1582","q":"Which Article of the Indian Constitution dealt with the citizenship at the commencement of the Constitution?","o":["Article 6","Article 5","Article 4","Article 3"],"a":1,"x":"Article 5 dealt with citizenship at the commencement of the Constitution (26 January 1950), based on domicile together with birth or residence.","e":"Articles 5–11 form Part II.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q1595","q":"In which year were the recommendations of the Mandal Commission implemented after the court's verdict?","o":["1991","1992","1990","1993"],"a":1,"x":"The Supreme Court upheld 27% OBC reservation from the Mandal Commission report in Indra Sawhney (November 1992); the key takes 1992 as the year it came into effect after the verdict.","e":"The same verdict set the 50% ceiling and excluded the 'creamy layer'.","src":["Patwari 17 Sep 2022 S2"],"k":"The V. P. Singh government's order came in 1990 and the post-verdict order in September 1993; DSSSB's key marks 1992, the verdict year."},{"id":"q1598","q":"Which Article of the Indian Constitution gives minorities the right to establish educational institutions?","o":["Article 32","Article 30","Article 15","Article 29"],"a":1,"x":"Article 30 gives religious and linguistic minorities the right to establish and run educational institutions of their choice.","e":"Article 29 protects any section of citizens' distinct language, script or culture.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q1604","q":"Which Article of the Constitution guarantees equality of opportunity for all citizens in matters relating to employment or appointment to any office under the State?","o":["Article 21","Article 17","Article 16","Article 15"],"a":2,"x":"Article 16 guarantees equality of opportunity in public employment; 16(4) allows reservation for backward classes.","e":"Article 15 bans discrimination in general.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q1624","q":"Article 51 'A', of Indian constitution contained in ______ of the Constitution deals with Fundamental Duties.","o":["Part IV A","Part III A","Part II A","Part V A"],"a":0,"x":"Article 51A, which lists the Fundamental Duties, is in Part IVA of the Constitution.","e":"Part IVA has only this one Article.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q0513","q":"Article 23 and 24 of the Indian Constitution deals with the ____________.","o":["Right to Freedom","Right to Equality","Right Against Exploitation","Cultural and Educational Rights"],"a":2,"x":"Articles 23 and 24 make up the Right against Exploitation: Article 23 bans human trafficking and forced labour (begar), and Article 24 bans child labour under 14 in factories, mines and hazardous work.","e":"Articles 25–28: freedom of religion.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0635","q":"According to which of the following Articles, the state shall not deny to any person equality before the law or the equal protection of the laws within the territory of India?","o":["24","14","32","20"],"a":1,"x":"Article 14: the State shall not deny to any person equality before the law or equal protection of the laws within India.","e":"It applies to 'any person', citizen or foreigner.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0674","q":"Article 19 to 22 of the Indian Constitution deals with the ____________.","o":["Right to Freedom","Right to Equality","Right Against Exploitation","Cultural and Educational Rights"],"a":0,"x":"Articles 19–22 form the Right to Freedom: six freedoms (19), protection in conviction (20), life and personal liberty (21), right to education (21A), and protection against arbitrary arrest (22).","e":"Article 21 has been read to include the right to privacy (2017).","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0712","q":"Article 29 and 30 of the Indian Constitution deals with the ____________.","o":["Right to Freedom","Right to Equality","Right Against Exploitation","Cultural and Educational Rights"],"a":3,"x":"Articles 29 and 30 are the Cultural and Educational Rights: protecting minorities' language, script and culture, and their right to set up educational institutions.","e":"Article 32 (constitutional remedies) was called the 'heart and soul' of the Constitution by Dr Ambedkar.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q1770","q":"Article 16 of the Indian constitution deals with _____________.","o":["Abolition of Untouchability","Equality before law","Equality of opportunity in matters of public employment","Abolition of titles"],"a":2,"x":"Article 16 guarantees equality of opportunity in public employment. Article 14 is equality before law, 17 abolishes untouchability, 18 abolishes titles.","e":"14 law, 15 discrimination, 16 jobs, 17 untouchability, 18 titles.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1853","q":"Which article of the Indian constitution deals with Protection of life and personal liberty?","o":["21","20","22","23"],"a":0,"x":"Article 21 protects life and personal liberty; the Supreme Court has read into it rights such as privacy, livelihood and a clean environment.","e":"Article 20: protection in conviction; 22: arrest and detention.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q2173","q":"In which year was the Swaran Singh Committee set up by the Indian Government?","o":["1973","1970","1979","1976"],"a":3,"x":"The Swaran Singh Committee was set up in 1976; on its recommendation the 42nd Amendment added Fundamental Duties (Article 51A).","e":"It suggested 8 duties; 10 were added.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2462","q":"Which of the following amendments of the Indian Constitution had inserted the Article 21A to provide free and compulsory education of all children?","o":["Seventy-sixth","Eightieth","Eighty-second","Eighty-sixth"],"a":3,"x":"The 86th Amendment (2002) inserted Article 21A, making free and compulsory education a fundamental right for children aged 6–14.","e":"It also added the 11th Fundamental Duty (Article 51A(k)).","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2466","q":"The Fundamental Duties of the Indian Constitution was inspired from which of the following country's constitution?","o":["USA","Canada","USSR","France"],"a":2,"x":"The idea of Fundamental Duties was borrowed from the constitution of the former USSR.","e":"Also from the USSR: the ideals of justice (social, economic, political) in the Preamble.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2505","q":"Which of the following articles of the Indian Constitution is related to the right against exploitation?","o":["Articles 18 and 19","Articles 20 and 21","Articles 22 and 23","Articles 23 and 24"],"a":3,"x":"The Right against Exploitation is in Articles 23 (ban on trafficking and forced labour) and 24 (ban on child labour in factories and mines).","e":"Articles 23–24: right against exploitation.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q0943","q":"Match the following Directive Principles of State Policy (DPSP) with their Articles. A. Right to work, to education and to public assistance in certain cases — i. Article 48; B. Organisation of agriculture and animal husbandry — ii. Article 41; C. Living wage etc. for workers — iii. Article 43; D. Promotion of international peace and security — iv. Article 51","o":["A-i, B-ii, C-iii, D-iv","A-iii, B-i, C-ii, D-iv","A-i, B-iii, C-ii, D-iv","A-ii, B-i, C-iii, D-iv"],"a":3,"x":"Article 41: right to work, education and public assistance in certain cases; Article 48: organisation of agriculture and animal husbandry; Article 43: living wage for workers; Article 51: promotion of international peace and security.","e":"41 work, 43 living wage, 48 agriculture and cows, 51 world peace.","src":["PRT 18 Feb 2026 S2"]},{"id":"q0944","q":"Match the Directive Principles with their Articles: A. Right to work, to education and to public assistance in certain cases; B. Organisation of agriculture and animal husbandry; C. Living wage etc. for workers; D. Promotion of international peace and security — i. Article 48, ii. Article 41, iii. Article 43, iv. Article 51.","o":["A-i, B-ii, C-iii, D-iv","A-iii, B-i, C-ii, D-iv","A-i, B-iii, C-ii, D-iv","A-ii, B-i, C-iii, D-iv"],"a":3,"x":"Right to work, education and public assistance – Article 41; organising agriculture and animal husbandry – Article 48; living wage for workers – Article 43; international peace and security – Article 51.","e":"DPSPs are in Part IV, Articles 36–51.","src":["PRT 18 Feb 2026 S2"]},{"id":"q0957","q":"Which of the following is NOT one of the categories under which the Directive Principles of State Policy have been classified?","o":["Cultural heritage principles","Principles and policies related to international peace and security","Gandhian principles","Economic and social principles"],"a":0,"x":"Directive Principles are usually grouped as socialistic (economic and social), Gandhian and liberal-intellectual (including international peace and security). 'Cultural heritage principles' is not such a category.","e":"Gandhian principles: village panchayats, cottage industries, prohibition, cow protection.","src":["PRT 18 Feb 2026 S2"]},{"id":"q1036","q":"Which of the following is constitutionally prohibited under the Right against Exploitation?","o":["Contract workers in offices","Bonded labour in brick kilns","Employing adults at construction sites","Children working on family farms"],"a":1,"x":"Article 23 bans human trafficking, begar and other forced labour; bonded labour at brick kilns is exactly what it forbids. The Bonded Labour System (Abolition) Act, 1976 enforces it.","e":"Article 24 bans children under 14 in factories, mines and hazardous work.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1141","q":"What is the primary constitutional protection given by Article 31B regarding the Ninth Schedule?","o":["It allows the temporary suspension of Fundamental Rights during emergency provisions.","It safeguards Acts in the 9th Schedule from being declared void for violating Fundamental Rights.","It bars judicial review of all future amendments made to Part III of the Constitution.","It empowers High Courts to validate laws repugnant to the Directive Principles."],"a":1,"x":"Article 31B (added by the 1st Amendment, 1951) protects Acts placed in the Ninth Schedule from being struck down for violating Fundamental Rights.","e":"In I. R. Coelho (2007) the Supreme Court ruled such laws added after 24 April 1973 can still be tested against the basic structure.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1150","q":"Which statement correctly reflects the constitutional status and function of the Directive Principles of State Policy?","o":["They represent the fundamental obligations of citizens in a democratic polity and are enforceable in courts.","They are non-justiciable but act as essential guidelines for the state in ensuring socio- economic justice.","They are judicially enforceable, similar to Fundamental Rights, and override conflicting laws.","They are temporary provisions adopted by Parliament to be repealed after the implementation of the first Five-Year Plan"],"a":1,"x":"Directive Principles are non-justiciable (Article 37): courts cannot enforce them, but they are fundamental in governance and guide the state towards social and economic justice.","e":"Dr Ambedkar called them 'novel features' of the Constitution; the idea comes from Ireland.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1279","q":"Which Article among the Fundamental Rights prohibits the employment of children in factories, stating that 'no child below the age of fourteen years shall be employed to work in any factory or mine or engaged in any other hazardous employment'?","o":["Article 19","Article 24","Article 31","Article 14"],"a":1,"x":"Article 24 prohibits employing children below 14 in factories, mines or other hazardous work.","e":"Right against exploitation = Articles 23 and 24.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1286","q":"What does the Indian Constitution say about the Directive Principles of State Policy?","o":["They override rights during a national emergency.","They are not enforceable but guide the governance of the state.","They are legally binding and enforceable by courts.","They are optional and can be ignored by the government."],"a":1,"x":"Directive Principles are not enforceable by courts, but they are fundamental in governance and guide the state in making laws (Article 37).","e":"Fundamental Rights are justiciable; DPSPs are not.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1471","q":"Which Article of the Indian Constitution provides protection of life and personal liberty?","o":["Article 29","Article 25","Article 21","Article 19"],"a":2,"x":"Article 21: no person shall be deprived of life or personal liberty except according to procedure established by law.","e":"Maneka Gandhi (1978) held the procedure must be 'just, fair and reasonable'.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1511","q":"In which of the following Articles of the Indian Constitution have the provisions regarding 'Rights of citizenship of certain migrants to Pakistan' been discussed?","o":["Article 3","Article 7","Article 13","Article 23"],"a":1,"x":"Article 7 covers the citizenship rights of people who migrated to Pakistan after 1 March 1947: they are not citizens of India unless they came back under a resettlement permit.","e":"Article 6: migrants from Pakistan to India. Article 8: persons of Indian origin living abroad.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1560","q":"Which Part of the Indian Constitution deals with Fundamental Duties?","o":["Part VIB","Part IIA","Part IVA","Part VB"],"a":2,"x":"Part IVA (Article 51A) deals with Fundamental Duties, added by the 42nd Amendment (1976).","e":"Fundamental Duties are not enforceable in court.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0838","q":"Which of the following statements about Fundamental Rights are correct? 1. Article 17 abolishes untouchability and forbids its practice in any form. 2. The concept of equality before law is taken from the British Constitution. 3. Article 15 prohibits discrimination against any citizen on grounds of religion, race, caste, sex or place of birth.","o":["Only 1 and 2","All 1, 2 and 3","Only 3","Only 2 and 3"],"a":1,"x":"All three are correct: Article 17 abolishes untouchability; 'equality before law' comes from Britain; Article 15 bans discrimination on religion, race, caste, sex or place of birth.","e":"'Equal protection of laws' in Article 14 comes from the USA.","src":["PGT 26 Sep 2025"]},{"id":"q0854","q":"Which statements about the rights guaranteed under Article 19 are correct? 1. The right to form associations or unions or co-operative societies. 2. The right to move freely throughout the territory of India. 3. The right to seek foreign employment.","o":["3 only","1, 2 and 3 only","1 and 2 only","1 only"],"a":2,"x":"Statements 1 and 2 are right: Article 19(1)(c) gives the right to form associations and unions, and 19(1)(d) the right to move freely in India. There is no Article 19 right to foreign employment.","e":"Article 19 has six freedoms; the right to property, 19(1)(f), was removed in 1978.","src":["PGT 14 Jul 2025"]}]},{"id":"union","n":"President, Prime Minister and Parliament","qs":[{"id":"q0075","q":"On whose advice does the President summon or prorogue Parliament sessions and dissolve the Lok Sabha?","o":["The Election Commission","The Chief Justice","The Speaker","The Council of Ministers"],"a":3,"x":"Under Article 74 the President acts on the advice of the Council of Ministers headed by the Prime Minister, including when summoning and proroguing Parliament or dissolving the Lok Sabha.","e":"Article 85 is the summon/prorogue/dissolve power; the advice is binding after the 42nd and 44th Amendments.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0076","q":"The Rajya Sabha in India is also known as the _______.","o":["Legislative Council","Upper Council","Council of States","National Assembly"],"a":2,"x":"The Rajya Sabha is the Council of States, the upper house that represents the states and UTs; it is a permanent body that is never dissolved.","e":"Lok Sabha = House of the People. One-third of Rajya Sabha members retire every two years.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0109","q":"Who among the following has the power to promulgate ordinances during the recess of Parliament, as per Article 123?","o":["The Speaker of Lok Sabha","The Chief Justice of India","The Prime Minister","The President of India"],"a":3,"x":"Article 123 lets the President issue ordinances when Parliament is not in session; an ordinance lapses six weeks after Parliament reassembles unless approved.","e":"Governors have the same power for states under Article 213.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0221","q":"Who is the executive head of the government at the central level in India?","o":["The Vice President","The Prime Minister","The President","The Chief Justice of India"],"a":2,"x":"Under Article 53 the executive power of the Union is vested in the President, the formal (constitutional) head of the executive. Real power is used by the Council of Ministers led by the Prime Minister.","e":"The President is the nominal head; the Prime Minister is the real head of government.","src":["ASO 20 Aug 2025 S1"],"k":"Many books call the Prime Minister the 'real executive head'; this question's key takes the constitutional head, the President."},{"id":"q0223","q":"Who is the only President of India to have been elected unopposed?","o":["Dr. Shankar Dayal Sharma","Dr. Neelam Sanjiva Reddy","Dr. Rajendra Prasad","Dr. APJ Abdul Kalam"],"a":1,"x":"Neelam Sanjiva Reddy is the only President elected unopposed, in 1977.","e":"Dr Rajendra Prasad is the only President elected twice.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0263","q":"The Parliament of India consists of the _____.","o":["Lok Sabha and the President","Lok Sabha and the Rajya Sabha","Lok Sabha, the Rajya Sabha and the President of India","Rajya Sabha and the President"],"a":2,"x":"Under Article 79, Parliament consists of the President and two Houses: the Rajya Sabha (Council of States) and the Lok Sabha (House of the People).","e":"The President is part of Parliament but not a member of either House.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0274","q":"Which of the following is a key difference between Standing Committees and Ad hoc Committees of the Indian Parliament?","o":["Standing Committees are elected, while Ad hoc Committees are nominated.","Standing Committees are permanent, while Ad hoc Committees are temporary and task specific.","Standing Committees deal with financial matters, while Ad hoc Committees deal with legislative matters.","Standing Committees report to the Speaker, while Ad hoc Committees report to the House."],"a":1,"x":"Standing committees are permanent and meet all the time (for example the Public Accounts Committee). Ad hoc committees are formed for one task and end when it is done.","e":"An example of an ad hoc committee is a Joint Committee on a particular bill.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0305","q":"As per the Constitution, the executive power of the Central Government is vested in the _____.","o":["Vice President","Prime Minister","Parliament","President"],"a":3,"x":"Article 53: the executive power of the Union is vested in the President, used directly or through subordinate officers.","e":"For states, Article 154 vests it in the Governor.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0320","q":"Which of the following statements about the role of the President in India’s parliamentary system is correct?","o":["The President’s assent is mandatory for a bill to become law.","A bill becomes law immediately after it is passed by both Houses.","The President has no role in summoning or dissolving the Houses.","The Indian system follows the American pattern of governance."],"a":0,"x":"A bill becomes law only after the President's assent (Article 111), even after both Houses pass it.","e":"On a non-money bill the President may return it once for reconsideration.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0388","q":"Which of the following is the maximum permissible strength that the Rajya Sabha can have?","o":["240","300","245","250"],"a":3,"x":"Article 80 fixes the maximum strength of the Rajya Sabha at 250: 238 elected from states and UTs, and 12 nominated by the President.","e":"Present strength is 245.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0468","q":"Which of the following is the second-highest Constitutional position in India?","o":["President of India","Home Minister of India","Prime Minister of India","Vice President of India"],"a":3,"x":"The Vice President is the second-highest constitutional office in India and is the ex-officio Chairman of the Rajya Sabha.","e":"The Prime Minister comes after them in the order of precedence.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1575","q":"Which article of the Constitution lays down the maximum strength of Rajya Sabha as 250?","o":["Article 67","Article 79","Article 80","Article 56"],"a":2,"x":"Article 80 fixes the Rajya Sabha's maximum strength at 250 (238 elected + 12 nominated).","e":"Article 81 sets the composition of the Lok Sabha.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q1580","q":"The President used to nominate two members of Anglo-Indian Community to Lok Sabha till which year, which now has been abolished?","o":["2019","2016","2020","2017"],"a":2,"x":"The President could nominate two Anglo-Indian members to the Lok Sabha (Article 331) until January 2020; the 104th Amendment (2019) ended this.","e":"The same amendment extended SC/ST reservation by 10 years, to 2030.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q0552","q":"The quorum for the meeting of the Rajya Sabha is fixed at __________ of the total members.","o":["one-tenth","one-seventh","one-sixth","one-ninth"],"a":0,"x":"The quorum of each House of Parliament is one-tenth of its total membership (Article 100).","e":"Presiding officers: Lok Sabha Speaker; Rajya Sabha Chairman (the Vice President).","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0593","q":"Who among the following is the ex-officio chairman of the Rajya Sabha?","o":["Vice President of India","Finance Minister of India","President of India","Prime Minister of India"],"a":0,"x":"The Vice President is the ex-officio Chairman of the Rajya Sabha (Article 89).","e":"The Deputy Chairman is elected from among Rajya Sabha members.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0753","q":"As of April 2020, the membership of the Rajya Sabha contains a provision for how many nominated members?","o":["20","12","16","18"],"a":1,"x":"The President nominates 12 members to the Rajya Sabha for special knowledge in literature, science, art and social service (Article 80).","e":"The two Anglo-Indian seats in the Lok Sabha ended in 2020.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q1772","q":"Which of the following statement regarding Eligibility for election of Vice President is correct? I. He has completed the age of thirty five years. II. He is Qualified for election as a member of the council of states.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Under Article 66 a Vice-President must be a citizen of India, at least 35 years old and qualified for election as a member of the Rajya Sabha.","e":"President: qualified for the Lok Sabha; Vice-President: for the Rajya Sabha.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1812","q":"Which article of the Indian constitution deals with The President of India?","o":["52","54","55","53"],"a":0,"x":"Article 52 says there shall be a President of India; Article 53 vests the Union's executive power in him.","e":"52 President, 53 executive power, 54 election, 58 qualifications.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1815","q":"Which of the following statement regarding the President is correct? I. Article 54 of the Indian constitution deals with election of President. II. Article 58 of the Indian constitution deals with qualifications for election as President.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 54 covers the President's election (by an electoral college) and Article 58 the qualifications for election as President, so both are correct.","e":"Article 55: manner of election; 56: term; 61: impeachment.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1964","q":"Which article of the Indian Constitution deals with power of President to grant pardons etc. and to suspend, remit or commute sentences in certain cases?","o":["68","69","70","72"],"a":3,"x":"Article 72 gives the President power to grant pardons, reprieves, respites or remissions and to suspend, remit or commute sentences; Article 161 gives Governors a similar power.","e":"President: 72; Governor: 161.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q1965","q":"Which article of the Indian Constitution deals with Annual Financial Statement?","o":["109","110","111","112"],"a":3,"x":"Article 112 requires the President to lay the Annual Financial Statement (the Union Budget) before Parliament.","e":"112 budget, 113 grants, 114 appropriation, 117 financial bills.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2005","q":"Which article of the Indian Constitution deals with council of ministers to aid and advise President?","o":["70","71","74","75"],"a":2,"x":"Article 74: a Council of Ministers headed by the Prime Minister aids and advises the President, who must act on its advice (42nd and 44th Amendments).","e":"74 advises; 75 appoints.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2006","q":"Which article of the Indian Constitution deals with Appropriation Bills?","o":["114","112","111","110"],"a":0,"x":"Article 114 covers the Appropriation Bill, which authorises withdrawal of money from the Consolidated Fund of India.","e":"No money leaves the Consolidated Fund without an Appropriation Act.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2007","q":"Which of the following statement(s) regarding article 361 of the Indian Constitution is/are correct? I. No criminal proceedings what so even shall be instituted or continued against the President or the Governor of a state in any court during his term of office. II. No process for the arrest or imprisonment of the President or the Governor of a state, shall issue from any court during his term of office.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 361: no criminal proceedings can be started or continued, and no arrest or imprisonment ordered, against the President or a Governor during the term of office. Both statements are correct.","e":"Civil proceedings need two months' notice.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2050","q":"Which article of the Indian Constitution deals with the Attorney General of India?","o":["76","75","74","73"],"a":0,"x":"Article 76 deals with the Attorney General of India, the government's chief legal adviser, appointed by the President.","e":"Article 165: Advocate General of a state.","src":["Junior Clerk 12 Nov 2021 S3","Junior Clerk 13 Nov 2021 S1"]},{"id":"q2051","q":"Which article of the Indian Constitution deals with courts not to inquire into proceedings of parliament?","o":["121","117","122","119"],"a":2,"x":"Article 122 says courts shall not inquire into the proceedings of Parliament; Article 212 says the same for state legislatures.","e":"Parliament 122; state legislatures 212.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2096","q":"______ shall be ex officio chairman of the council of states and shall not hold any other office of profit.","o":["The Vice President","President","The Prime Minister","Attorney General of India"],"a":0,"x":"Under Article 64 the Vice-President is the ex-officio Chairman of the Rajya Sabha (Council of States) and holds no other office of profit.","e":"The Deputy Chairman is elected by the Rajya Sabha.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2133","q":"Which of the following statement regarding Parliament is correct? I. Article 83 of the Indian constitution deals with Duration of houses of parliament. II. Article 84 of the Indian constitution deals with Qualification for membership of parliament.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 83 deals with the duration of the Houses of Parliament and Article 84 with qualifications for membership, so both are correct.","e":"Lok Sabha minimum age 25; Rajya Sabha 30.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2174","q":"Which of the following articles of the Indian Constitution is related to the impeachment of the President?","o":["Article 52","Article 57","Article 61","Article 65"],"a":2,"x":"Article 61 lays down the procedure for impeaching the President for violating the Constitution; it needs a two-thirds majority in both Houses.","e":"Article 56: term; 57: re-election; 61: impeachment.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2175","q":"According to the 84th Amendment Act of 2001, till which year has the allocation of seats in the Lok Sabha to the states and the division of each state into territorial constituencies been frozen?","o":["2021","2023","2025","2026"],"a":3,"x":"The 84th Amendment (2001) froze the allocation of Lok Sabha seats to states and the delimitation of constituencies until the first census after 2026.","e":"The 42nd Amendment had first frozen seats on the 1971 census.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2421","q":"Which of the following articles of the Indian Constitution states that \"There shall be a Council of Ministers with the Prime Minister at the head to aid and advise the President\"?","o":["74(1)","74(2)","75(1)","75(2)"],"a":0,"x":"Article 74(1) says there shall be a Council of Ministers with the Prime Minister at its head to aid and advise the President.","e":"74(2): courts cannot inquire into the advice given.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2453","q":"Who out of the following is Shankar Dayal Sharma?","o":["Former President of India","Former Prime Minister of India","Former Governor of RBI","Former Home Minister of India"],"a":0,"x":"Dr Shankar Dayal Sharma was the ninth President of India (1992–97); before that he was Vice-President.","e":"Presidents in order: Venkataraman → S.D. Sharma → K.R. Narayanan.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2618","q":"Which article of the Indian Constitution deals with composition of the house of the people?","o":["79","80","81","84"],"a":2,"x":"Article 81 deals with the composition of the Lok Sabha (House of the People).","e":"Article 80: Rajya Sabha; 81: Lok Sabha.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2689","q":"Which article of the Indian Constitution deals with composition of the council of states?","o":["81","80","79","78"],"a":1,"x":"Article 80 deals with the composition of the Rajya Sabha (up to 250 members, 12 nominated).","e":"","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1320","q":"Which of the following articles of the Indian Constitution empowers each House of the Parliament to make rules for regulations, subject to the provisions of this Constitution, its procedure and the conduct of its business?","o":["Article 118(1)","Article 118(2)","Article 118(4)","Article 118(3)"],"a":0,"x":"Article 118(1) lets each House of Parliament make rules for its procedure and conduct of business, subject to the Constitution.","e":"Article 118(4): the Speaker presides over joint sittings.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1349","q":"The 91st Constitutional Amendment restricted the size of council of ministers to ________ of legislative members.","o":["18 percent","20 percent","10 percent","15 percent"],"a":3,"x":"The 91st Amendment (2003) capped the Council of Ministers at 15% of the total strength of the Lok Sabha or state Legislative Assembly.","e":"Small states must still have at least 12 ministers.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q2732","q":"A member of Lok Sabha should not be less than _______ years of age.","o":["20","25","30","35"],"a":1,"x":"A Lok Sabha member must be at least 25 years old; a Rajya Sabha member at least 30.","e":"Article 84.","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2734","q":"A bill that deals exclusively with money matters that are mentioned in Article _______ in Constitution is called a Money Bill.","o":["110","58","61","94"],"a":0,"x":"Article 110 defines a Money Bill: one dealing only with matters such as taxes, borrowing and the Consolidated Fund.","e":"The Speaker certifies a Money Bill.","src":["Ahlmad 16 Oct 2021 S1","PGT 31 Jul 2021 S1"]},{"id":"q0887","q":"According to which Amendment of the Constitution can the total number of ministers, including the Prime Minister, not exceed 15% of the Lok Sabha's strength?","o":["91st Amendment","42nd Amendment","44th Amendment","73rd Amendment"],"a":0,"x":"The 91st Amendment (2003) caps the Council of Ministers, including the PM, at 15% of the Lok Sabha's total strength (Article 75(1A)); the same cap applies to states, with a minimum of 12.","e":"It also tightened the anti-defection law by removing the 'split' exception.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0888","q":"Money Bills can be introduced only in _______.","o":["Rajya Sabha","Lok Sabha","Joint Sitting","either House"],"a":1,"x":"Under Article 109 a Money Bill can be introduced only in the Lok Sabha, and only on the President's recommendation; the Rajya Sabha can delay it for at most 14 days.","e":"The Speaker certifies what is a Money Bill.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0931","q":"According to the Constitution of India, which of the following is NOT a qualification for a Member of Parliament?","o":["Must be a citizen of India and make an oath or affirmation in the form set out in the Third Schedule","Must be at least 30 years old for the Rajya Sabha and at least 25 years old for the Lok Sabha","Must hold a degree from a university recognised by the University Grants Commission (UGC)","Must possess any additional qualifications prescribed by law made by Parliament"],"a":2,"x":"Article 84 requires an MP to be a citizen of India, to take the oath in the Third Schedule, to be at least 30 (Rajya Sabha) or 25 (Lok Sabha), and to meet any other qualification Parliament sets. No educational degree is required.","e":"The Representation of the People Act, 1951 sets the further conditions.","src":["PRT 18 Feb 2026 S1"]},{"id":"q0967","q":"Which Article of the Indian Constitution relates to the appointment of the Prime Minister of India?","o":["Article 80","Article 62","Article 60","Article 75"],"a":3,"x":"Article 75: the Prime Minister is appointed by the President, and other ministers on the PM's advice.","e":"Article 74: Council of Ministers aids and advises the President.","src":["PRT 18 Feb 2026 S3"]},{"id":"q0972","q":"Which statement correctly links constitutional provisions about ministers with the appropriate Schedules?","o":["A member disqualified under the Tenth Schedule cannot be appointed a minister for a specified period under Article 75(1B).","Under the Ninth Schedule, ministers hold office during the pleasure of the President.","The form of oath for ministers is laid down in the Second Schedule.","Collective responsibility of the Council of Ministers is enforced through the Fourth Schedule."],"a":0,"x":"Article 75(1B): a member disqualified for defection under the Tenth Schedule cannot become a minister until the end of that House's term or re-election. The ministers' oath forms are in the Third Schedule, not the Second.","e":"The 91st Amendment (2003) inserted Article 75(1B).","src":["PRT 18 Feb 2026 S3"]},{"id":"q1065","q":"How many times can the President return a bill passed by Parliament for reconsideration?","o":["Only once","Four times","Three times","More than four times"],"a":0,"x":"Under Article 111 the President can return a non-money bill to Parliament for reconsideration only once; if Parliament passes it again, the President must assent.","e":"Money bills cannot be returned.","src":["PRT 20 Feb 2026 S2"]},{"id":"q1255","q":"According to the Indian Constitution, the executive power of the Union is:","o":["Shared equally between the President and the Chief Justice of India","Vested solely in the Prime Minister","Exercised only during a national emergency","Vested in the President and exercised by him directly or through subordinate officers"],"a":3,"x":"Article 53: the executive power of the Union is vested in the President and exercised by him directly or through subordinate officers under the Constitution.","e":"Supreme command of the armed forces also rests with the President.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1257","q":"Which of the following statements is CORRECT regarding the term of office of the President of India?","o":["The President can only be removed by the Prime Minister or the Chief Justice of India.","The President continues in office even after the term ends, until a successor takes charge.","The President must vacate office exactly on the completion of five years.","The President holds office for six years and cannot resign."],"a":1,"x":"The President's term is five years, but under Article 56(1)(c) the President continues in office after the term ends until a successor takes charge.","e":"The President can resign by writing to the Vice President.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1414","q":"With reference to the constitutional provisions regarding Rajya Sabha, which of the following statements is correct?","o":["The Attorney General of India is the ex-officio chairman of the Rajya Sabha.","The Prime Minister of India is the ex-officio chairman of the Rajya Sabha.","The Vice-President of India is the ex-officio chairman of the Rajya Sabha.","The President of India is the ex-officio chairman of the Rajya Sabha."],"a":2,"x":"The Vice-President of India is the ex-officio Chairman of the Rajya Sabha (Article 64).","e":"The Vice-President is elected by an electoral college of members of both Houses.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1481","q":"Which Article of the Indian Constitution empowers the Vice President to act as President or discharge his functions during casual vacancies in the office or in the absence of the President?","o":["Article 72","Article 61","Article 65","Article 52"],"a":2,"x":"Article 65 lets the Vice President act as President when the office falls vacant (until a new election, within six months) or when the President is absent or ill.","e":"If both are vacant, the Chief Justice of India acts as President.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1500","q":"The impeachment charges on the President of India can be initiated in either House of Parliament. These charges should be signed by ___________ of members of that particular House.","o":["one-third","one-fourth","one-sixth","one-tenth"],"a":1,"x":"Impeachment charges against the President must be signed by at least one-fourth of the members of the House where they start, after 14 days' notice (Article 61).","e":"The charge must then be passed by a two-thirds majority of the total membership of each House.","src":["TGT 29 Aug 2025"]},{"id":"q1503","q":"Which of the following statements is/are correct regarding the executive powers of the Union vested in the President of India? 1. Article 53 deals with the executive powers of the President of India. 2. Article 75 requires the Prime Minister to communicate to the President regarding all decisions of the Union Council of Ministers. 3. Article 77 holds that all executive powers of the Union government shall be exercised in the name of the President.","o":["Only 1 and 3","1, 2 and 3","Only 1 and 2","Only 2 and 3"],"a":0,"x":"Statements 1 and 3 are correct: Article 53 vests executive power in the President, and Article 77 requires executive action in the President's name. The PM's duty to inform the President is in Article 78, not 75.","e":"Article 75 deals with the appointment of the PM and ministers.","src":["TGT 29 Aug 2025"]},{"id":"q0804","q":"The advice of the Council of Ministers is binding on the _______.","o":["President","Judiciary","Chief Justice","Speaker"],"a":0,"x":"Under Article 74(1) (as amended by the 42nd and 44th Amendments) the advice of the Council of Ministers binds the President, who may send it back once for reconsideration.","e":"In states, the Governor acts on the advice of the state Council of Ministers.","src":["PGT 22 Sep 2025"]}]},{"id":"judiciary","n":"Judiciary","qs":[{"id":"q0070","q":"Which was the fourth High Court to be established in India after Calcutta, Bombay and Madras?","o":["Delhi","Patna","Allahabad","Punjab"],"a":2,"x":"After Calcutta, Bombay and Madras (1862), the Allahabad High Court was set up in 1866 (first at Agra), making it the fourth.","e":"Its principal seat moved from Agra to Allahabad in 1869.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0103","q":"Match the Union Territories with their judiciaries: a. Andaman and Nicobar Islands, b. Daman and Diu, c. Lakshadweep, d. Puducherry — with i. Bombay High Court, ii. Calcutta High Court, iii. Madras High Court, iv. Kerala High Court.","o":["a-iv; b-i; c-iii; d-ii","a-i; b-ii; c-iii; d-iv","a-ii; b-i; c-iv; d-iii","a-iii; b-iv; c-ii; d-i"],"a":2,"x":"Andaman and Nicobar → Calcutta High Court; Daman and Diu → Bombay High Court; Lakshadweep → Kerala High Court; Puducherry → Madras High Court.","e":"Delhi is the only UT with its own High Court (1966); Jammu and Kashmir and Ladakh share one.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0111","q":"According to the Constitution of India, which Article specifies the provision for the establishment of a High Court in each state?","o":["Article 214","Article 231","Article 125","Article 212"],"a":0,"x":"Article 214 says there shall be a High Court for each state; Article 231 lets Parliament set up one common High Court for two or more states.","e":"Oldest High Court: Calcutta (1862).","src":["ASO 18 Aug 2025 S3"]},{"id":"q0342","q":"Which of the following has the original jurisdiction to settle disputes between the Union and the States?","o":["Supreme Court","High Court","Lok Sabha","Parliament"],"a":0,"x":"Under Article 131 the Supreme Court has original (and exclusive) jurisdiction over disputes between the Union and states, or between states.","e":"Article 32 (writs for Fundamental Rights) is also original jurisdiction.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0351","q":"Article 241 in Part VIII of the Indian Constitution deals with _____.","o":["the administration of Union Territories","capitals of Union Territories","the High Courts for Union Territories","special provisions with respect to Delhi"],"a":2,"x":"Article 241 lets Parliament set up a High Court for a Union Territory or declare a court to be its High Court.","e":"Delhi got its own High Court in 1966.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0385","q":"Which of the given Articles underlines the composition of the Supreme Court in India?","o":["Article 110","Article 124","Article 150","Article 324"],"a":1,"x":"Article 124 sets up the Supreme Court and its composition: the Chief Justice of India and other judges fixed by Parliament (now up to 34 in total).","e":"SC judges retire at 65; High Court judges at 62.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0476","q":"Which of the following High Courts has its jurisdiction over more than one state or union territory?","o":["Allahabad","Delhi","Patna","Bombay"],"a":3,"x":"The Bombay High Court covers Maharashtra, Goa, and Dadra and Nagar Haveli and Daman and Diu.","e":"The Guwahati High Court covers Assam, Nagaland, Mizoram and Arunachal Pradesh.","src":["ASO 27 Aug 2025 S1"]},{"id":"q2132","q":"Which of the following writ is mentioned in the Indian constitution? I. Habeas Corpus II. Prohibition","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Constitution provides five writs: habeas corpus, mandamus, prohibition, certiorari and quo warranto (Articles 32 and 226).","e":"Habeas corpus: 'produce the body'.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2134","q":"Which of the following statement regarding Supreme court is correct? I. Article 124 of the Indian constitution deals with Establishment and Constitution of Supreme court. II. Article 125 of the Indian constitution deals with salaries of Judges.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 124 establishes and constitutes the Supreme Court and Article 125 deals with judges' salaries, so both are correct.","e":"Article 124(4): removal of judges.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2419","q":"On which date was the Supreme Court of India established?","o":["January 26th, 1950","January 29th, 1950","January 30th, 1950","January 31st, 1950"],"a":0,"x":"The Supreme Court of India came into existence on 26 January 1950, when the Constitution came into force, replacing the Federal Court.","e":"First Chief Justice: H.J. Kania.","src":["Junior Clerk 15 Nov 2021 S1"],"k":"The Court was formally inaugurated two days later, on 28 January 1950; DSSSB's key uses 26 January, when it came into existence."},{"id":"q2464","q":"Which of the following articles of the Indian Constitution empowers the Supreme Court for original jurisdiction to deal with any dispute between the Centre and a state?","o":["Article 125","Article 131","Article 138","Article 141"],"a":1,"x":"Article 131 gives the Supreme Court original jurisdiction over disputes between the Centre and states, or between states.","e":"Article 32: writs; 136: special leave petitions.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2619","q":"Which article of the Indian Constitution deals with conferment on the supreme court of powers to issue certain writs?","o":["135","138","139","136"],"a":2,"x":"Article 139 allows Parliament to give the Supreme Court power to issue writs for purposes other than enforcing fundamental rights.","e":"Article 32: writs for fundamental rights.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2690","q":"Which article of the Indian Constitution deals with appointment of Ad hoc judges?","o":["126","123","127","125"],"a":2,"x":"Article 127 lets the Chief Justice of India appoint ad hoc judges to the Supreme Court when there is no quorum.","e":"Article 128: retired judges at sittings.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1323","q":"Which of the following constitutional amendment had replaced the Collegium System of appointing judges to the Supreme Court and High Courts with the National Judicial Appointments Commission (NJAC)?","o":["97th","98th","96th","99th"],"a":3,"x":"The 99th Amendment (2014) created the National Judicial Appointments Commission to replace the collegium; the Supreme Court struck it down in 2015.","e":"The collegium system remains in force.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1325","q":"In which of the following countries did the concept of Public Interest Litigation originate?","o":["USA","Ireland","Russia","Canada"],"a":0,"x":"Public Interest Litigation began in the USA in the 1960s; in India, Justices P. N. Bhagwati and V. R. Krishna Iyer pioneered it in the late 1970s and 1980s.","e":"Hussainara Khatoon (1979) is often cited as India's first PIL.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q0929","q":"Under which Act have Lok Adalats been given statutory status?","o":["Legal Services Authorities Act, 1997","Legal Services Authorities Act, 1987","Legal Services Authorities Act, 2000","Legal Services Authorities Act, 1990"],"a":1,"x":"The Legal Services Authorities Act, 1987 (in force 1995) gave Lok Adalats statutory status; their awards are final and binding.","e":"Article 39A (free legal aid) is the constitutional basis.","src":["PRT 18 Feb 2026 S1"]},{"id":"q0980","q":"Which of the following CORRECTLY illustrates the long-term constitutional consequence of the Kesavananda Bharati judgment in the context of parliamentary attempts at asserting supremacy?","o":["The constitutional review exercise post-1980 successfully removed all restrictions on amending fundamental rights","The 42nd Amendment annulled the basic structure doctrine, making Parliament sovereign in all constitutional matters.","Despite the 42nd Amendment, the Supreme Court in Minerva Mills reaffirmed the basic structure doctrine, limiting constitutional amendments.","The Minerva Mills judgment overturned Kesavananda and declared the Preamble non- justiciable."],"a":2,"x":"Kesavananda Bharati (1973) created the basic structure doctrine. The 42nd Amendment tried to put amendments beyond judicial review, but Minerva Mills (1980) struck that down and reaffirmed the basic structure.","e":"Minerva Mills held that the balance between Fundamental Rights and DPSPs is itself part of the basic structure.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1046","q":"Which of the following constitutional amendments is CORRECTLY matched with its judicial implication?","o":["54th Amendment – Revised the salary structure of judges in constitutional courts","15th Amendment – Increased the number of judges in the Supreme Court","42nd Amendment – Reduced the retirement age of Supreme Court judges to 60 years","44th Amendment – Raised the retirement age of High Court judges to 65 years"],"a":0,"x":"The 54th Amendment (1986) raised the salaries of Supreme Court and High Court judges and let Parliament change them by ordinary law.","e":"The 15th Amendment (1963) raised the retirement age of High Court judges from 60 to 62.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1062","q":"Which power does the Supreme Court have regarding laws passed by the legislature?","o":["The power to veto","The power to review","The power to enforce","The power to amend"],"a":1,"x":"The Supreme Court has the power of judicial review: it can declare laws void if they break the Constitution (Articles 13, 32, 131). It cannot veto, amend or enforce laws the way the executive does.","e":"Judicial review is part of the basic structure.","src":["PRT 20 Feb 2026 S2"]},{"id":"q1087","q":"Where was the first Lok Adalat camp held in India?","o":["Gujarat","Andhra Pradesh","Rajasthan","West Bengal"],"a":0,"x":"The first Lok Adalat camp was held in Gujarat (Junagadh) in March 1982.","e":"Lok Adalat awards are final; no appeal lies against them.","src":["PRT 23 Feb 2026 S2"]},{"id":"q1094","q":"Lok Adalats in India were given statutory status under the Legal Services Authorities Act passed in the year ________.","o":["1977","1967","1987","1997"],"a":2,"x":"Lok Adalats got statutory status under the Legal Services Authorities Act, 1987, which came into force in 1995.","e":"Article 39A (free legal aid) is the constitutional basis.","src":["PRT 23 Feb 2026 S2"]},{"id":"q1180","q":"All Lok Adalat proceedings are deemed judicial proceedings under the Bharatiya Nyaya Sanhita, passed in the year __________.","o":["2020","2016","2018","2023"],"a":3,"x":"Section 22(3) of the Legal Services Authorities Act, 1987 deems Lok Adalat proceedings to be judicial proceedings under the penal law, now the Bharatiya Nyaya Sanhita, 2023 (which replaced the IPC from 1 July 2024).","e":"An award of a Lok Adalat is final; no appeal lies against it.","src":["PRT 31 Mar 2026 S1"]},{"id":"q1507","q":"What is the minimum number of judges in a Constitution Bench of the Supreme Court of India?","o":["7","5","3","8"],"a":1,"x":"Article 145(3): cases involving a substantial question of constitutional interpretation are heard by a bench of at least five judges (a Constitution Bench).","e":"Kesavananda Bharati had 13 judges, the largest bench.","src":["TGT 24 Aug 2025 S1"]},{"id":"q0836","q":"Which of the following statements regarding jurisdiction of Subordinate Courts in India is INCORRECT?","o":["The district judge is the highest judicial authority in the district.","There are three tiers of civil and criminal courts below the High Court.","The district judge exercises both judicial and administrative powers.","The organisational structure and jurisdiction of these courts are laid down by the Union Government and they are the same in every state."],"a":3,"x":"The incorrect statement is that subordinate courts are organised uniformly by the Union. Their structure and jurisdiction are set by state laws and vary slightly between states.","e":"The district judge is the top judicial officer of a district.","src":["PGT 26 Sep 2025"]},{"id":"q0868","q":"In which case did the Supreme Court rule that constitutional amendments can be challenged in courts?","o":["S. R. Bommai case","Minerva Mills case","Kesavananda Bharati case","Vishaka case"],"a":2,"x":"In Kesavananda Bharati (1973) the Supreme Court held that Parliament can amend the Constitution but not its basic structure, so amendments can be challenged in court.","e":"13-judge bench, 7:6 verdict.","src":["PGT 24 Sep 2025"]}]},{"id":"states","n":"States, Union Territories, Delhi and Local Bodies","qs":[{"id":"q0021","q":"_________ provides that all the seats in a municipality shall be filled by the persons selected by direct elections from territorial constituencies in the municipal area.","o":["Article 243-R","Article 253-A","Article 243-A","Article 243-G"],"a":0,"x":"Article 243R (Part IXA, added by the 74th Amendment, 1992) says all seats in a municipality are filled by direct election from territorial constituencies (wards).","e":"The panchayat equivalent is Article 243C. Part IX = Panchayats; Part IXA = Municipalities.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0022","q":"Legislative Assembly DOES NOT exist in which of the following Union Territories?","o":["Jammu and Kashmir","Puducherry","Ladakh","Delhi"],"a":2,"x":"Ladakh became a Union Territory without a legislature under the Jammu and Kashmir Reorganisation Act, 2019; Jammu and Kashmir became a UT with one.","e":"UTs with an elected assembly: Delhi, Puducherry, Jammu and Kashmir.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0080","q":"Which of the following ministries exercises the administrative control over the Cantonment Boards established under the Cantonment Act?","o":["Ministry of Defence","Ministry of Housing and Urban Affairs","Ministry of Home Affairs","Ministry of Panchayati Raj"],"a":0,"x":"Cantonment Boards run civic affairs in military cantonments and are under the Ministry of Defence, now under the Cantonments Act, 2006.","e":"India has 62 notified cantonments; the Station Commander usually heads the board.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0105","q":"The North Cachar Hills district is an autonomous district council of which state?","o":["Mizoram","Assam","Nagaland","Tripura"],"a":1,"x":"The North Cachar Hills district (now Dima Hasao) of Assam has an autonomous district council under the Sixth Schedule.","e":"Sixth Schedule states: Assam, Meghalaya, Tripura, Mizoram.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0106","q":"Administration of Union Territories is mentioned in which of the following Parts of the Constitution of India?","o":["Part-VIII","Part-II","Part-VII","Part-IX"],"a":0,"x":"Part VIII (Articles 239–242) deals with Union Territories; each UT is run by the President through an administrator.","e":"Article 239AA (69th Amendment, 1991) gives Delhi its special status as the National Capital Territory.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0157","q":"Which of the following is a Union Territory with a Legislative Assembly?","o":["Andaman and Nicobar Islands","Chandigarh","Puducherry","Lakshadweep"],"a":2,"x":"Puducherry has a Legislative Assembly (Government of Union Territories Act, 1963), as do Delhi and Jammu and Kashmir.","e":"Chandigarh, Lakshadweep, and Andaman and Nicobar have no legislature.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0158","q":"What is the significance of the President’s powers in relation to state legislation under Article 200 of the Indian Constitution?","o":["The President can pass state laws without consulting the state legislature.","The President can dissolve the state legislature unilaterally.","The President’s assent is required for all the bills passed by a state legislature.","The President can reject any bill passed by a state legislature that was referred to him by the Governor of the state."],"a":3,"x":"Under Article 200 a Governor can reserve a state bill for the President; under Article 201 the President may then assent or withhold assent.","e":"Money bills reserved for the President cannot be returned to the state legislature for reconsideration.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0183","q":"Which of the following is NOT a duty of the Chief Minister under Article 167 of the Indian Constitution?","o":["To submit proposals for international treaties to the Governor","To communicate all decisions of the Council of Ministers to the Governor","To furnish information called for by the Governor about state administration","To submit matters decided by a Minister but not considered by the Council for consideration"],"a":0,"x":"Article 167 makes the Chief Minister communicate Cabinet decisions to the Governor, give information the Governor asks for, and put a minister's decision before the whole council if asked. Proposing international treaties is not a state function.","e":"Treaties are a Union List subject (entry 14).","src":["ASO 19 Aug 2025 S3"]},{"id":"q0345","q":"Which Constitutional Article deals with Union Territories?","o":["Article 244","Article 239","Article 152","Article 220"],"a":1,"x":"Article 239 says each Union Territory is administered by the President through an administrator appointed by the President.","e":"Article 239A: legislature for Puducherry. Article 239AA: Delhi.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0360","q":"In 1956, India had 14 states and _______ Union Territories.","o":["7","9","6","8"],"a":2,"x":"The States Reorganisation Act, 1956 organised India into 14 states and 6 union territories.","e":"It took effect on 1 November 1956.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0387","q":"Articles 239 to 241 in Part VIII of the Indian Constitution deal with the _________.","o":["High Courts","Parliament","Union Territories","Supreme Court"],"a":2,"x":"Articles 239–241 in Part VIII deal with Union Territories: their administration, Delhi and Puducherry, and High Courts for UTs.","e":"Part VIII was reshaped by the 7th Amendment (1956).","src":["ASO 21 Aug 2025 S3"]},{"id":"q0393","q":"What is the minimum age requirement for an Indian citizen to be appointed as Governor of any state in India?","o":["45 years","35 years","30 years","50 years"],"a":1,"x":"Article 157: a Governor must be a citizen of India and at least 35 years old.","e":"Same minimum age as the President and Vice President.","src":["ASO 21 Aug 2025 S3"]},{"id":"q1586","q":"Which Amendment Act, 1991 of Indian Constitution accorded a special status to the Union Territory of Delhi by designating it as the National Capital Territory of Delhi?","o":["47th","69th","55th","76th"],"a":1,"x":"The 69th Amendment (1991) added Articles 239AA and 239AB, making Delhi the National Capital Territory with an elected Legislative Assembly.","e":"The Balakrishnan Committee recommended the change.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q1855","q":"Which of the following state legislature has two houses? I. Maharashtra II. Kerala","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Maharashtra has a bicameral legislature (Assembly and Council); Kerala has only a Legislative Assembly.","e":"Six states have Legislative Councils: UP, Bihar, Maharashtra, Karnataka, Telangana, Andhra Pradesh.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1856","q":"Through which constitutional amendment part IX was inserted in the Indian constitution?","o":["44th","86th","73rd","11th"],"a":2,"x":"Part IX (The Panchayats) was inserted by the 73rd Amendment (1992); Part IXA (Municipalities) by the 74th.","e":"73rd = panchayats; 74th = municipalities.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1967","q":"Which of the following subject(s) is/are mentioned in the Eleventh Schedule of the Indian constitution? I. Fisheries II. Family Welfare","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Eleventh Schedule (73rd Amendment) lists 29 subjects for panchayats, including fisheries and family welfare.","e":"11th: panchayats (29 subjects); 12th: municipalities (18).","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2052","q":"Which of the following article(s) is/are mentioned in sixth schedule of the Indian constitution? I. 244(2) II. 275(1)","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Sixth Schedule (administration of tribal areas in Assam, Meghalaya, Tripura and Mizoram) is referred to in Articles 244(2) and 275(1).","e":"Fifth Schedule: other scheduled areas.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2135","q":"In which year did the Seventy fourth amendment of the Indian constitution take place?","o":["1992","1998","2002","1990"],"a":0,"x":"The 74th Amendment Act (1992) added Part IXA and the Twelfth Schedule, giving municipalities constitutional status.","e":"73rd: panchayats; 74th: municipalities.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2420","q":"In which year did the Supreme Court rule that the office of governor of a state is not an employment under the Central government?","o":["In 1961","In 1965","In 1974","In 1979"],"a":3,"x":"In Hargovind Pant v. Raghukul Tilak (1979) the Supreme Court held that a Governor's office is an independent constitutional office, not employment under the Central Government.","e":"The Governor is appointed by the President (Article 155).","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2508","q":"Which Constitutional Amendment had converted Dadra and Nagar Haveli into a union territory?","o":["10th","11th","12th","13th"],"a":0,"x":"The 10th Amendment (1961) made Dadra and Nagar Haveli a Union Territory after its liberation from Portugal.","e":"12th Amendment (1962): Goa, Daman and Diu.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2509","q":"Which of the following was the first state to establish the Panchayati Raj system in India?","o":["Tamil Nadu","Uttar Pradesh","Maharashtra","Rajasthan"],"a":3,"x":"Rajasthan was the first state to set up Panchayati Raj: PM Nehru inaugurated it at Nagaur on 2 October 1959; Andhra Pradesh followed.","e":"It followed the Balwant Rai Mehta Committee (1957).","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2549","q":"With which of the following is the P. K. Thungon Committee of 1989 related to?","o":["Basic features of the Constitution","Appointment of judges in Supreme Court","Appointment of judges in High Court","Local government"],"a":3,"x":"The P.K. Thungon Committee (1989) recommended constitutional recognition for local government (panchayats), leading to the 73rd Amendment.","e":"Other panchayat committees: Balwant Rai Mehta (1957), Ashok Mehta (1977), L.M. Singhvi (1986).","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2692","q":"Through which constitutional amendment special provisions with respect to the state of Nagaland were added in the Indian constitution?","o":["Tenth","Twelfth","Thirteenth","Eleventh"],"a":2,"x":"The 13th Amendment (1962) added Article 371A, with special provisions for Nagaland, which became a state in 1963.","e":"371A Nagaland, 371B Assam, 371C Manipur.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1312","q":"In which year was the Fazl Ali Commission appointed?","o":["1952","1953","1954","1951"],"a":1,"x":"The States Reorganisation Commission, chaired by Fazl Ali with K. M. Panikkar and H. N. Kunzru, was appointed in December 1953; its report led to the States Reorganisation Act, 1956.","e":"The Dhar Commission (1948) and JVP Committee (1948–49) came earlier.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q0892","q":"According to Article 371F of the Indian Constitution, how many members does the Legislative Assembly of Sikkim have?","o":["25","32","45","65"],"a":1,"x":"Article 371F (36th Amendment, 1975, when Sikkim became a state) says Sikkim's Legislative Assembly shall have at least 30 members; it has 32.","e":"Sikkim is India's least populous state; 22nd state, 1975.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0911","q":"Which of the following statements is correct about the relationship of the State Council of Ministers with the Governor?","o":["They advise the Governor on governmental affairs.","They assist the Governor in drafting state laws.","They supervise the Governor's actions.","They hold office at the pleasure of the Governor."],"a":0,"x":"Article 163: a Council of Ministers headed by the Chief Minister aids and advises the Governor in exercising his functions.","e":"Article 164(1): the Chief Minister is appointed by the Governor.","src":["PRT 17 Feb 2026 S3"],"k":"Under Article 164(1) ministers also hold office during the pleasure of the Governor, so option D is technically true as well; DSSSB's key is A."},{"id":"q0915","q":"Which Article of the Constitution says there shall be a Minister in charge of tribal welfare in Chhattisgarh, Jharkhand, Madhya Pradesh and Odisha?","o":["Article 164","Article 166","Article 168","Article 170"],"a":0,"x":"The proviso to Article 164(1) requires a Minister in charge of tribal welfare in Chhattisgarh, Jharkhand, Madhya Pradesh and Odisha. The 94th Amendment (2006) replaced Bihar with Chhattisgarh and Jharkhand.","e":"The same minister may also handle SC and OBC welfare.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0973","q":"Which qualification is required for a person to be appointed Governor of an Indian state?","o":["Is a Member of Parliament","Belongs to the state of appointment and has completed 30 years of age","Has served as a judge of a High Court","Is a citizen of India and has completed 35 years of age"],"a":3,"x":"A Governor must be a citizen of India and at least 35 years old (Article 157).","e":"By convention a Governor is not from the state being governed, but this is not a legal requirement.","src":["PRT 18 Feb 2026 S3"]},{"id":"q0981","q":"The Governor of a State shall be appointed by the ___________ by warrant under his hand and seal.","o":["Prime Minister of India","Chief Justice of India","Respective State's Chief Minister","President of India"],"a":3,"x":"Under Article 155 the President appoints the Governor by warrant under hand and seal; the Governor holds office at the President's pleasure (Article 156).","e":"Normal term: five years.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1006","q":"Which of the following statements is CORRECT regarding the term of office of a Governor in India?","o":["The Governor holds office during the pleasure of the President and may resign by writing to the President.","The Legislative Assembly of the State elects the Governor.","The Governor cannot resign once appointed until the five-year term is complete.","The governor can be removed only through impeachment in Parliament on the recommendation of the Chief Justice of India."],"a":0,"x":"A Governor holds office during the pleasure of the President (Article 156) and may resign by writing to the President. There is no impeachment for Governors.","e":"The Governor is appointed, not elected.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1019","q":"Which of the following Panchayat levels is responsible for district-level planning in India?","o":["Block Panchayat","Lok Sabha","Gram Panchayat","Zila Parishad"],"a":3,"x":"The Zila Parishad is the district-level tier of Panchayati Raj and coordinates district planning; Gram Panchayats and Block (Panchayat) Samitis sit below it.","e":"A District Planning Committee (Article 243ZD) consolidates the district plan.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1029","q":"According to the Constitution of India, which of the following pairs of urban bodies and their corresponding areas is CORRECTLY matched?","o":["Municipal Corporation – Transitional area moving from rural to urban","Municipal Board – Rural area with no urban characteristic","Nagar Panchayat – Fully developed urban metropolis","Municipal Council – Smaller urban area"],"a":3,"x":"Article 243Q: a Nagar Panchayat is for an area in transition from rural to urban, a Municipal Council for a smaller urban area, and a Municipal Corporation for a larger urban area.","e":"Added by the 74th Amendment (1992), Part IXA.","src":["PRT 19 Feb 2026 S3"]},{"id":"q1081","q":"In whose name is the administration and governance of a state in India carried out?","o":["The Chief Minister","The State Cabinet Secretary","The Governor","The President"],"a":2,"x":"The state's executive power is vested in the Governor (Article 154), and all executive actions of a state government are taken in the Governor's name (Article 166).","e":"At the Union level, actions are in the President's name (Article 77).","src":["PRT 23 Feb 2026 S2"]},{"id":"q1099","q":"According to Article 243C, which statement about the composition of and elections to panchayats is correct?","o":["Panchayat constituencies are formed only on geographical boundaries, not population.","As far as practicable, the ratio between population and the number of seats should be the same throughout the panchayat area.","Only district-level panchayats are filled by direct election; other levels are appointed.","The Governor nominates all panchayat members from local administrative bodies."],"a":1,"x":"Article 243C: as far as practicable, the ratio of population to seats should be the same throughout a panchayat area; seats are filled by direct election from territorial constituencies.","e":"Chairpersons at the intermediate and district levels are elected indirectly.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1113","q":"Which statement correctly describes the constitutional provisions for the Governor?","o":["Parliament cannot confer any function on authorities subordinate to the Governor.","The Governor exercises the state's executive power only through the Chief Minister.","The executive power of the state is vested in the Governor and exercised by him directly or through subordinate officers.","The Governor is the supreme law-making authority in the state."],"a":2,"x":"Article 154: the state's executive power is vested in the Governor, exercised directly or through subordinate officers; Parliament or the state legislature may confer functions on authorities under the Governor.","e":"In practice the Governor acts on the advice of the Chief Minister-led council.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1146","q":"According to the Indian Constitution, the powers and functions of a Gram Sabha at the village level are determined by:","o":["The Election Commission of India","The Legislature of the respective State by law","The Governor, through public notification","The Union Parliament"],"a":1,"x":"Article 243A: a Gram Sabha exercises the powers and performs the functions that the State Legislature provides by law.","e":"The 73rd Amendment (1992) added Part IX (Panchayats).","src":["PRT 26 Mar 2026 S2"]},{"id":"q1151","q":"Which department maintains land use records in India?","o":["Ministry of Environment","Forest Survey of India","Planning Commission","Land Revenue Department"],"a":3,"x":"Land-use and land ownership records (such as khasra and khatauni) are kept by the state Land Revenue Department through patwaris and tehsildars.","e":"The Digital India Land Records Modernisation Programme digitises these records.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1200","q":"Which option correctly reflects the constitutional provision on dual membership of state legislatures?","o":["The Constitution permits permanent dual membership to strengthen federal unity.","A person may hold seats in two or more state legislatures with the President's consent.","A person elected to more than one state legislature must resign from all but one within the time set by rules made by the President.","The First Schedule permits dual membership if both assemblies approve."],"a":2,"x":"Article 190(2): if a person is elected to the legislatures of two or more states, he must resign from all but one within the time set by rules made by the President, or all his seats fall vacant.","e":"Article 101 covers the same situation for Parliament.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1247","q":"The reservation of seats for SCs and STs in every municipality is based on which criterion?","o":["The State Government's discretion on the basis of social justice","The recommendation of the State Finance Commission","The proportion of the SC/ST population in the total population of the municipal area","A fixed percentage set by the Election Commission"],"a":2,"x":"Article 243T: seats for SCs and STs in every municipality are reserved in proportion to their share of the total population of that municipal area.","e":"Not less than one-third of seats are reserved for women.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1260","q":"The salary and allowances of the Chief Minister of the state are ___________.","o":["Determined by the Pay Commission of the state","Determined by the Governor of the state","Determined by the Parliament","Determined by the State Legislature"],"a":3,"x":"The salaries and allowances of the Chief Minister and other ministers are decided by the State Legislature by law (Article 164(5)).","e":"The Governor's emoluments are fixed by Parliament.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1385","q":"Which Constitutional Amendment Act promoted the appointment of the same person as a Governor for two or more states?","o":["Ninth","Third","Fifth","Seventh"],"a":3,"x":"The 7th Amendment (1956) allowed the same person to be Governor of two or more states (Article 153).","e":"The same amendment allowed a common High Court for two or more states.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1409","q":"As of 2022, which of the following states has the highest number of assembly constituencies?","o":["Maharashtra","Gujarat","Uttar Pradesh","Tamil Nadu"],"a":2,"x":"Uttar Pradesh has the most assembly constituencies, 403, and also the most Lok Sabha seats (80).","e":"Next: West Bengal (294), Maharashtra (288).","src":["TGT 25 Jun 2023 S1"]},{"id":"q1410","q":"What is the minimum age requirement, as prescribed by the Constitution, to become a member of a Panchayat?","o":["18 years","28 years","36 years","21 years"],"a":3,"x":"Under Article 243F the minimum age for a panchayat member is 21 years.","e":"Minimum age for the state legislative assembly: 25 years.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1454","q":"The power of the governor to promulgate Ordinances during recess of the Legislature is defined in Article ______ of the Indian Constitution.","o":["221","217","209","213"],"a":3,"x":"Article 213 lets a Governor issue ordinances when the state legislature is not in session; the President has the same power under Article 123.","e":"An ordinance must be approved within six weeks of the legislature reassembling.","src":["TGT 25 Jun 2023 S3"]},{"id":"q1535","q":"The Governor of a state addresses his resignation to __________.","o":["The President of India","The Prime Minister of India","The Union Home Minister","The Chief Minister of the state"],"a":0,"x":"A Governor resigns by writing to the President of India (Article 156).","e":"The President also appoints the Governor.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1536","q":"Under Article ______ of the Constitution, the Uttarakhand Assembly passed a proposal in 2010 making Hindi the official language and Sanskrit the second official language of the state.","o":["199","310","345","234"],"a":2,"x":"Article 345 lets a state legislature adopt one or more languages as official languages of the state; Uttarakhand used it in 2010 to make Sanskrit its second official language.","e":"Himachal Pradesh also made Sanskrit a second official language (2019).","src":["TGT 24 Aug 2025 S3"]},{"id":"q1557","q":"The Administrator of Dadra and Nagar Haveli is concurrently the Administrator of which Union Territory?","o":["Andaman and Nicobar Islands","Puducherry","Daman and Diu","Lakshadweep"],"a":2,"x":"The Administrator of Dadra and Nagar Haveli also served as Administrator of Daman and Diu; since 26 January 2020 the two are merged into one UT.","e":"Its capital is Daman.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0784","q":"The first municipal corporation in Madras, India, was established in the year _____.","o":["1688","1702","1704","1726"],"a":0,"x":"The Madras Municipal Corporation, set up in 1688, is the oldest municipal body in India and among the oldest in the Commonwealth outside Britain.","e":"Lord Ripon's 1882 resolution is called the Magna Carta of local self-government.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0789","q":"Which of the following does Article 243D of the Indian Constitution mandate regarding women's representation in the Panchayati Raj Institutions (PRIs)?","o":["Reservation of at least 25% of seats for women","Reservation of at least 50% of seats for women","Reservation of at least one-third (33%) of seats for women","No reservation for women"],"a":2,"x":"Article 243D reserves at least one-third of seats (and of chairperson posts) in Panchayati Raj institutions for women.","e":"Many states, such as Bihar, have raised this to 50%.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0817","q":"According to the Constitution of India, in which of the following areas can a Nagar Panchayat be set up in India?","o":["Entirely rural","Transitional area","Metropolitan city","Industrial region"],"a":1,"x":"Article 243Q provides a Nagar Panchayat for a transitional area (changing from rural to urban), a Municipal Council for a smaller urban area, and a Municipal Corporation for a larger urban area.","e":"The 74th Amendment (1992) added Part IXA on municipalities.","src":["PGT 22 Sep 2025"]},{"id":"q0866","q":"Article 371 of the Indian Constitution provides special provisions for which of the following states?","o":["Maharashtra and Madhya Pradesh","Maharashtra and Karnataka","Gujarat and Rajasthan","Maharashtra and Gujarat"],"a":3,"x":"Article 371 allows special provisions for Maharashtra (Vidarbha, Marathwada) and Gujarat (Saurashtra, Kutch), such as separate development boards.","e":"371A Nagaland, 371B Assam, 371C Manipur, and so on.","src":["PGT 24 Sep 2025"]}]},{"id":"federal","n":"Centre–State Relations and Emergency","qs":[{"id":"q0184","q":"How does the Indian Constitution ensure that the Union Government maintains control over national security and defence?","o":["By providing each state with its own military forces","By empowering states to sign international treaties","By placing defence and external affairs under the Union List","By allowing states to manage their defence forces"],"a":2,"x":"Defence, armed forces and external affairs are on the Union List of the Seventh Schedule, so only Parliament can make laws on them.","e":"Police and public order are on the State List.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0269","q":"What mechanism allows the Central Government to issue directives to states to ensure compliance with union laws?","o":["Finance Commission directives","Emergency proclamations","Constitutional provisions under Article 256","Constitutional provisions under Article 236"],"a":2,"x":"Article 256 obliges states to follow Union laws, and lets the Union give states directions to ensure that.","e":"Under Article 365, if a state ignores Union directions, the President may hold that its government cannot be carried on constitutionally.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0307","q":"Which Article of the Constitution gives the Central Government the duty to protect states against external aggression and internal disturbance?","o":["Article 356","Article 352","Article 355","Article 256"],"a":2,"x":"Article 355 makes it the Union's duty to protect every state against external aggression and internal disturbance, and to ensure it runs by the Constitution.","e":"Article 352: national emergency. Article 356: President's Rule.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0317","q":"What is the relationship between the Union Government and the States when a national emergency is declared?","o":["The State governments lose all their legislative powers.","The Union Government gains the power to legislate on State subjects.","The President's powers are limited to defence and foreign affairs.","The States retain full autonomy and only national matters are affected."],"a":1,"x":"During a national emergency (Article 352), Parliament can make laws on State List subjects (Article 250) and the Union can direct states. States keep their governments but lose autonomy.","e":"Such laws stop working six months after the emergency ends.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0594","q":"Which among the following Schedules in the Indian Constitution is associated with the central government, state, and concurrent lists of responsibilities?","o":["Sixth","Ninth","Eighth","Seventh"],"a":3,"x":"The Seventh Schedule sets out the Union List, State List and Concurrent List.","e":"Originally 97, 66 and 47 subjects.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q1771","q":"Which of the following subjects are mentioned in the concurrent list of the Indian constitution? I. Trust and Trustees II. Actionable Wrongs III. Forests","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Trusts and trustees, actionable wrongs, and forests (moved there by the 42nd Amendment) are all in the Concurrent List.","e":"42nd Amendment moved education, forests, weights and measures, wildlife and justice administration to the Concurrent List.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1854","q":"Which of the following subjects are mentioned in the Union list of the Indian constitution? I. War and Peace II. Extradition III. Railways","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"War and peace, extradition and railways are all Union List subjects (List I of the Seventh Schedule).","e":"Union List ~100 subjects; State List ~61; Concurrent ~52.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1857","q":"Article ______ of the Indian constitution deals with Proclamation of Emergency.","o":["354","352","357","356"],"a":1,"x":"Article 352 deals with a Proclamation of (National) Emergency; Article 356 with President's Rule in states and Article 360 with Financial Emergency.","e":"352 national, 356 state, 360 financial.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1966","q":"Which of the following statement(s) regarding Residuary powers of legislation is/are correct? I. Parliament has exclusive power to make any law with respect to any matter not enumerated in the concurrent list or state list. II. Such power shall include the power of making any law imposing a tax not mentioned in either of concurrent or state list.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 248: Parliament has exclusive power over any matter not listed in the Concurrent or State List (residuary powers), including taxes not mentioned in either list.","e":"Residuary powers lie with the Union (Canadian model).","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2463","q":"Under which of the following of the Constitution is ‘Police’ under the State list?","o":["Article 132","5th Schedule","7th Schedule","Article 330"],"a":2,"x":"'Police' and 'public order' are State List subjects in the Seventh Schedule.","e":"Seventh Schedule = three lists.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2620","q":"Which of the following subject(s) is/are mentioned in the Union list? I. Central Bureau of Intelligence and Investigation II. Extradition III. Insurance","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"The Central Bureau of Intelligence and Investigation, extradition and insurance are all Union List subjects.","e":"Banking and insurance are central subjects.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2691","q":"How many subjects are included in the union list?","o":["102","66","47","97"],"a":3,"x":"The Union List originally had 97 subjects; after amendments it now has about 100.","e":"State List: originally 66; Concurrent: originally 47.","src":["Junior Clerk 16 Nov 2021 S2"],"k":"The count of 97 is the original number; current texts give about 100 Union List subjects."},{"id":"q1358","q":"The 48th Constitutional Amendment facilitated the extension of President’s rule in ___________ beyond one year without meeting the two special conditions for such extension.","o":["Assam","Sikkim","Mizoram","Punjab"],"a":3,"x":"The 48th Amendment (1984) allowed President's Rule in Punjab to be extended beyond one year without the usual conditions (national emergency and Election Commission certification).","e":"Article 356 normally allows President's Rule for at most three years.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q0984","q":"Article 359A of the Indian Constitution is related to which of the following states?","o":["Meghalaya","Punjab","Jammu & Kashmir","Assam"],"a":1,"x":"Article 359A (added by the 59th Amendment, 1988) allowed extra emergency powers for Punjab; it lapsed after two years and was later repealed.","e":"The 63rd Amendment (1989) omitted it.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1016","q":"Under which of the following circumstances can the Parliament legislate on a matter in the State List?","o":["When the Governor of a State requests intervention by the Union Government","When the Rajya Sabha passes a resolution by a two-thirds majority in the national interest","When the Lok Sabha passes a resolution by a simple majority in the national interest","When the President gives assent without recommendation"],"a":1,"x":"Under Article 249, Parliament can make law on a State List subject if the Rajya Sabha passes a resolution by a two-thirds majority of members present and voting, saying it is in the national interest.","e":"Such a resolution lasts one year and can be renewed.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1028","q":"Which of the following statements regarding the Inter-State Council under Article 263 is CORRECT?","o":["It can be established by the President if deemed necessary in the public interest.","It is a permanent constitutional body.","It can be established by the Chief Justice of India if deemed necessary in the public interest.","It has adjudicatory powers to resolve interstate river water disputes."],"a":0,"x":"Article 263 lets the President set up an Inter-State Council if public interest needs it; it is not permanent, advisory only, and does not decide river water disputes (Article 262 covers those). One was set up in 1990 on the Sarkaria Commission's advice.","e":"The Prime Minister chairs it.","src":["PRT 19 Feb 2026 S3"]},{"id":"q1103","q":"According to Article 352 of the Indian Constitution, the proclamation of emergency is the responsibility of whom, if satisfied that a grave emergency exists whereby the security of India or any part of its territory is threatened by war, external aggression or armed rebellion?","o":["Defence Minister of India","Defence Secretary of India","Vice President of India","President of India"],"a":3,"x":"Under Article 352 the President proclaims a National Emergency when satisfied that India's security is threatened by war, external aggression or armed rebellion, but only on the Cabinet's written advice (44th Amendment).","e":"'Armed rebellion' replaced 'internal disturbance' in 1978.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1117","q":"According to which Article of the Indian Constitution 'shall it be the duty of the Union to protect every State against external aggression and internal disturbance and to ensure that the government of every State is carried on in accordance with the provisions of this Constitution'?","o":["Article 455","Article 555","Article 355","Article 255"],"a":2,"x":"Article 355 makes it the Union's duty to protect every state against external aggression and internal disturbance, and to ensure each state is governed according to the Constitution.","e":"Article 356: President's Rule if that fails.","src":["PRT 26 Mar 2026 S1"]},{"id":"q1168","q":"Article 254(2) permits a State law on a Concurrent List subject to prevail over a Parliamentary law only if:","o":["The law is approved by two or more States","The State law is passed by a special majority","The law receives the President’s assent after being reserved","The law is certified by the Chief Justice of the State"],"a":2,"x":"Article 254(2): if a State law on a Concurrent List subject conflicts with a central law, the State law prevails in that State if it was reserved for the President and received his assent.","e":"Parliament can still override it later.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1429","q":"The grants-in-aid by the Union government to certain states, charged on the Consolidated Fund of India, are described in Article ______ of the Constitution.","o":["475","175","275","375"],"a":2,"x":"Article 275 provides statutory grants-in-aid to states in need, charged on the Consolidated Fund of India.","e":"Article 282 allows discretionary grants for any public purpose.","src":["TGT 25 Jun 2023 S2"]},{"id":"q0859","q":"Which of the following schedules deals with the division of powers between the Union and the States?","o":["Fifth Schedule","Second Schedule","Seventh Schedule","First Schedule"],"a":2,"x":"The Seventh Schedule divides powers between the Union and states through the Union, State and Concurrent Lists.","e":"Residuary powers rest with Parliament (Article 248).","src":["PGT 14 Jul 2025"]}]},{"id":"bodies","n":"Constitutional Bodies, Acts and Elections","qs":[{"id":"q0064","q":"How many national parties were recognised at the time of the first Lok Sabha elections 1951-52?","o":["5","10","14","8"],"a":2,"x":"14 parties were recognised as national parties in the first general elections of 1951–52.","e":"Congress won 364 of 489 seats.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0115","q":"Who among the following was the Prime Minister of India when the Right to Information Bill was passed in Parliament?","o":["Rajiv Gandhi","Narendra Modi","Atal Bihari Vajpayee","Dr. Manmohan Singh"],"a":3,"x":"The Right to Information Act was passed in 2005, when Dr Manmohan Singh was Prime Minister; it came fully into force on 12 October 2005.","e":"The President at the time was Dr A. P. J. Abdul Kalam.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0196","q":"Who among the following was the President of India when the Right to Information Bill was passed in the Parliament?","o":["KR Narayan","Dr. APJ Abdul Kalam","Dr. Shankar Dayal Sharma","Ramnath Kovind"],"a":1,"x":"When Parliament passed the RTI Bill in 2005 the President was Dr A. P. J. Abdul Kalam, who gave assent on 15 June 2005.","e":"The Prime Minister then was Dr Manmohan Singh.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0271","q":"Which of the following is an independent statutory body established under an Act of 2013 of the Parliament of India?","o":["Attorney General of India","Election Commission","Lokpal and Lokayuktas","Comptroller and Auditor General of India"],"a":2,"x":"The Lokpal and Lokayuktas Act, 2013 set up the Lokpal as an independent statutory anti-corruption body. The other options are constitutional posts.","e":"The first Lokpal, Justice Pinaki Chandra Ghose, took office in 2019.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0432","q":"Who was the first Indian Chairman of the Union Public Service Commission after Independence?","o":["V. S. Hejmadi","R. N. Banerjee","N. Govindarajan","H. K. Kripalani"],"a":3,"x":"H. K. Kripalani was the first Indian chairman of the (Federal) Public Service Commission after Independence (1947–49); R. N. Banerjee chaired it when it became the UPSC in 1950.","e":"The UPSC works under Articles 315–323; it was first set up in 1926 (Lee Commission).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0437","q":"UPSC is a constitutional body that discharges the duties and functions assigned to it under Article __________.","o":["317","320","323","313"],"a":1,"x":"Article 320 lists the functions of the UPSC and the State PSCs: conducting examinations and advising on recruitment, promotions and disciplinary matters.","e":"Article 315: PSCs for the Union and states. Article 317: removal of members.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0439","q":"Which commission is mainly constituted to recommend the distribution of tax revenue between the Union and the states, and among the states?","o":["Law Commission","Competition Commission of India","Finance Commission","Planning Commission"],"a":2,"x":"The Finance Commission (Article 280) recommends how tax revenue is shared between the Union and states and among states; it is set up every five years.","e":"The first Finance Commission was chaired by K. C. Neogy (1951).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0475","q":"In which Article of the Constitution of India is the Goods and Services Tax Council defined?","o":["Article 324","Article 315","Article 279A","Article 338A"],"a":2,"x":"Article 279A (added by the 101st Amendment, 2016) creates the GST Council, chaired by the Union Finance Minister with state finance ministers as members.","e":"GST came into force on 1 July 2017.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1573","q":"In which Lok Sabha election was the highest voter turnout recorded?","o":["17th","1st","16th","4th"],"a":0,"x":"The 17th Lok Sabha election (2019) recorded the highest voter turnout of any general election, about 67.4%.","e":"The 2024 (18th) election recorded about 65.8%.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1588","q":"The National Commission for Scheduled Tribes (NCST) was established by amending ______.","o":["Article 245","Article 166","Article 338","Article 344"],"a":2,"x":"The National Commission for Scheduled Tribes was created in 2004 when the 89th Amendment (2003) split the old Article 338 commission, adding Article 338A for STs.","e":"Article 338 now covers the National Commission for SCs.","src":["Patwari 20 Aug 2022 S2"],"k":"Strictly, the NCST sits in Article 338A, inserted by amending Article 338."},{"id":"q1589","q":"Who is the chairman of the Fifteenth Finance Commission?","o":["N. K. Singh","A. N. Jha","Anoop Singh","Ramesh Chand"],"a":0,"x":"N. K. Singh chaired the Fifteenth Finance Commission (2021-26 award period).","e":"The Sixteenth Finance Commission (2026-31) is chaired by Arvind Panagariya.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q1596","q":"The Right to Information Act was enforced in ______.","o":["2007","2004","2006","2005"],"a":3,"x":"The Right to Information Act, 2005 came fully into force on 12 October 2005.","e":"It set up the Central and State Information Commissions.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q1746","q":"The National Human Rights Commission (NHRC) of India was established on:","o":["2 October","15 August","26 January","12 October"],"a":3,"x":"The National Human Rights Commission was set up on 12 October 1993 under the Protection of Human Rights Act, 1993.","e":"It is a statutory body, not a constitutional one.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1813","q":"Which of the following language is mentioned in the Eighth Schedule of the Indian constitution? I. Dogri II. Bodo","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Dogri and Bodo, along with Maithili and Santhali, were added to the Eighth Schedule by the 92nd Amendment (2003), which now lists 22 languages.","e":"92nd Amendment = 4 languages added in 2003.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1814","q":"In which year did the sixty first amendment of the Indian constitution take place?","o":["1990","2002","1982","1988"],"a":3,"x":"The 61st Amendment Act, 1988 lowered the voting age from 21 to 18 for Lok Sabha and Assembly elections (in force from 1989).","e":"Article 326 governs adult suffrage.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q2008","q":"In which year did the Twentieth amendment of the Indian constitution took place?","o":["1962","1964","1968","1966"],"a":3,"x":"The 20th Amendment (1966) validated appointments of district judges in Uttar Pradesh that a Supreme Court ruling had put in doubt.","e":"19th (1966) abolished election tribunals.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2094","q":"Which of the following languages are mentioned in the Eighth Schedule of the Indian constitution? I. Bengali II. Assamese II. Nepali","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Bengali and Assamese were among the original Eighth Schedule languages, and Nepali was added by the 71st Amendment (1992), so all three are listed.","e":"22 languages in the Eighth Schedule now.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2127","q":"Who has been appointed as the first Lokpal of India?","o":["Pinaki Chandra Ghose","Abhilasha Kumari","P K Mohanty","Aditya Mishra"],"a":0,"x":"Justice Pinaki Chandra Ghose became India's first Lokpal in March 2019 under the Lokpal and Lokayuktas Act, 2013.","e":"Lokpal = anti-corruption ombudsman.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2131","q":"Which part of the Indian constitution deals with elections?","o":["XVII","XVIII","XIV","XV"],"a":3,"x":"Part XV (Articles 324–329) of the Constitution deals with elections and the Election Commission.","e":"Article 324: Election Commission.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2176","q":"Which of the following is a constitutional body?","o":["National Human Rights Commission","National Commission for Women","National Consumer Disputes Redressal Commission","National Commission for Scheduled Castes"],"a":3,"x":"The National Commission for Scheduled Castes is a constitutional body (Article 338). The NHRC, NCW and NCDRC are statutory bodies set up by Acts.","e":"Constitutional = named in the Constitution; statutory = created by an Act.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2422","q":"Which of the following is the tenure of the election commissioners of India?","o":["Six years or until they reach the age of sixty-five","Six years or until they reach the age of sixty-three","Five years or until they reach the age of sixty-three","Five years or until they reach the age of sixty-five"],"a":0,"x":"The Chief Election Commissioner and Election Commissioners hold office for six years or until age 65, whichever comes first.","e":"The CEC is removed like a Supreme Court judge.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2465","q":"Which was the first tribal language to be included in the eighth schedule of the Indian Constitution?","o":["Shompen","Nepali","Tulu","Bodo"],"a":3,"x":"Bodo, a tribal language of Assam, was added to the Eighth Schedule by the 92nd Amendment (2003), with Dogri, Maithili and Santhali.","e":"Santhali, another tribal language, was added in the same amendment.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2547","q":"Which of the following constitutional amendments brought down the minimum age for voting from 21 years to 18 years?","o":["52nd","61st","73rd","74th"],"a":1,"x":"The 61st Amendment Act (1988) lowered the voting age from 21 to 18 years.","e":"Article 326: adult suffrage.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2551","q":"Which of the following is the Article 324 of the Indian Constitution related to?","o":["Supreme Court","Election Commission","Governor","Central Vigilance Commission"],"a":1,"x":"Article 324 vests the superintendence, direction and control of elections in the Election Commission.","e":"Part XV: Articles 324–329.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q1156","q":"What is a key feature of the multi-member Election Commission?","o":["The Commission handles local body elections.","All members share equal decision-making power.","The Chief Election Commissioner has more power.","Only one Commissioner is appointed at a time."],"a":1,"x":"In the multi-member Election Commission (since 1993), the CEC and Election Commissioners have equal powers and salary, and differences are decided by majority.","e":"The CEC can be removed only like a Supreme Court judge.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1210","q":"In which year was the 'Food Safety and Standards Act' enacted to consolidate laws relating to food and lay down science-based standards?","o":["2006","2009","2000","2004"],"a":0,"x":"The Food Safety and Standards Act, 2006 merged earlier food laws and set up FSSAI (2008) to lay down science-based standards for food.","e":"FSSAI works under the Ministry of Health and Family Welfare.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1232","q":"Which of the following accurately reflects the constitutional impact of the 71st Amendment Act?","o":["The legal voting age was reduced and electoral participation expanded.","Rural self-government was constitutionalised through institutional reforms.","The National Capital Territory was given legislative and executive autonomy.","The Eighth Schedule was expanded by recognising three additional regional languages."],"a":3,"x":"The 71st Amendment (1992) added Konkani, Manipuri and Nepali to the Eighth Schedule of languages.","e":"The 92nd Amendment (2003) added Bodo, Dogri, Maithili and Santhali.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1469","q":"Article 315 of the Indian Constitution is related to which of the following?","o":["Finance Commission","Public Service Commissions for the Union and for the States","Administrative tribunals","Election Commission"],"a":1,"x":"Article 315 provides Public Service Commissions for the Union and the states; the functions come under Article 320.","e":"The Finance Commission is Article 280; the Election Commission is Article 324.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1504","q":"The National Commission for Backward Classes consists of a Chairman, Vice-Chairman and _____ members.","o":["3","5","4","6"],"a":0,"x":"The National Commission for Backward Classes, made constitutional by the 102nd Amendment (2018, Article 338B), has a Chairperson, a Vice-Chairperson and three other members.","e":"NCSC = Article 338, NCST = Article 338A.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1525","q":"The National Commission for Scheduled Castes has 1 Chairperson, ______ Vice-Chairperson and ______ members.","o":["1; 3","1; 5","2; 4","2; 3"],"a":0,"x":"The National Commission for Scheduled Castes (Article 338) has a Chairperson, a Vice-Chairperson and three other members, appointed by the President.","e":"The separate National Commission for STs (Article 338A) came with the 89th Amendment (2003).","src":["TGT 24 Aug 2025 S3"]},{"id":"q0765","q":"Under which Act was the Central Information Commission (CIC) established?","o":["Indian Evidence Act, 1872","Right to Information Act, 2005","Information Technology Act, 2000","Public Records Act, 1993"],"a":1,"x":"The Central Information Commission was set up in 2005 under the Right to Information Act, 2005; it is a statutory body.","e":"It hears appeals when public authorities deny information.","src":["PGT 25 Sep 2025"]},{"id":"q0778","q":"In which year was India's first Armed Forces Tribunal set up?","o":["2011","2009","2012","2010"],"a":1,"x":"The Armed Forces Tribunal was set up under the Armed Forces Tribunal Act, 2007, and started working in August 2009, with its principal bench in New Delhi.","e":"It hears service and court-martial matters of the Army, Navy and Air Force.","src":["PGT 25 Sep 2025"]},{"id":"q0783","q":"Match the Finance Commission with its Chairman: A) Eighth, B) Sixth, C) Eleventh, D) Third — I) A. K. Chanda, II) K. Brahmananda Reddy, III) A. M. Khusro, IV) Y. B. Chavan.","o":["A-I, B-II, C-IV, D-III","A-IV, B-III, C-II, D-I","A-IV, B-II, C-III, D-I","A-I, B-II, C-III, D-IV"],"a":2,"x":"Chairmen: Eighth Finance Commission — Y. B. Chavan; Sixth — K. Brahmananda Reddy; Eleventh — A. M. Khusro; Third — A. K. Chanda.","e":"First Finance Commission: K. C. Neogy. Fifteenth: N. K. Singh. Sixteenth: Arvind Panagariya.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0791","q":"In which of the following years was the Dowry Prohibition Act brought into effect?","o":["1986","2013","2005","1961"],"a":3,"x":"The Dowry Prohibition Act, 1961 makes giving or taking dowry an offence.","e":"Section 80 of the Bharatiya Nyaya Sanhita (earlier IPC 304B) deals with dowry death.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0813","q":"Which of the following is an example of a Constitutional Body in India?","o":["National Human Rights Commission","Central Bureau of Investigation","Election Commission of India","NITI Aayog"],"a":2,"x":"The Election Commission of India is a constitutional body under Article 324. NHRC is statutory; the CBI and NITI Aayog are neither constitutional nor statutory.","e":"Other constitutional bodies: UPSC, Finance Commission, CAG.","src":["PGT 22 Sep 2025"]},{"id":"q0825","q":"In which of the following years was the Family Courts Act introduced in India to promote conciliation in family and marriage-related disputes?","o":["1984","1975","1989","1992"],"a":0,"x":"The Family Courts Act, 1984 set up family courts to settle marriage and family disputes through conciliation.","e":"A state must set up a family court in cities with over 10 lakh population.","src":["PGT 26 Sep 2025"]},{"id":"q0849","q":"Which of the following bodies is responsible for the recruitment of personnel for All India Services?","o":["National Recruitment Agency","Union Public Service Commission","Staff Selection Commission","State Public Service Commission"],"a":1,"x":"The UPSC recruits for the All India Services (IAS, IPS, IFoS) through the Civil Services Examination; the Union government then appoints them.","e":"Article 312 lets Parliament create new All India Services.","src":["PGT 14 Jul 2025"]},{"id":"q0862","q":"Which of the following languages is NOT included in the Eighth Schedule of the Indian Constitution?","o":["Konkani","Magahi","Santhali","Odia"],"a":1,"x":"The 8th Schedule lists 22 languages; Konkani, Manipuri and Nepali were added in 1992 and Santhali, Maithili, Bodo and Dogri in 2003. Magahi is not included.","e":"Odia is among the original 14 languages.","src":["PGT 24 Sep 2025"]}]}]});
